window.HYMNS=(window.HYMNS||[]).concat([{"id": "pp096", "cat": "pp", "title": "عصر النهضة", "text": "ق) عصر النهضة راجع تاني\nاهتفي يا كنيسة بأغاني\nخلوا الزيت مالي المصابيح\nضُم ايمانك ويا ايماني\n\n1- ده رسل الرب الاطهار\nانتظروا فنالوا سكيب النار\nواحنا بنطلب بأسم البار\nمواعيد الوقت الأخراني\n\nق) عصر النهضة راجع تاني\nاهتفي يا كنيسة بأغاني\nخلوا الزيت مالي المصابيح\nضُم ايمانك ويا ايماني\n\n2- راجعين بخضوع ليك يا إلهنا\nطالبين ملكوتك في حياتنا\nتايبين عن شرنا وطُرُقنا\nتاركين العالم الفاني\n\nق) عصر النهضة راجع تاني\nاهتفي يا كنيسة بأغاني\nخلوا الزيت مالي المصابيح\nضُم ايمانك ويا ايماني\n\n3- اتمسكي يا كنيسة بالوعد\nولا تنسي من الناس حد\nده عمره البيت ما هيتملي مجد\nإلا بحضوره الرباني\n\nق) عصر النهضة راجع تاني\nاهتفي يا كنيسة بأغاني\nخلوا الزيت مالي المصابيح\nضُم ايمانك ويا ايماني\n\n4- ما في ابواب تقوى عليكي\nيا كنيسة ده وعد الله ليكي\nانك تغلبي باسم فاديكي\nوتدوسي الفكر الشيطاني \n\nق) عصر النهضة راجع تاني\nاهتفي يا كنيسة بأغاني\nخلوا الزيت مالي المصابيح\nضُم ايمانك ويا ايماني\n\n5- المجد لك يا مخلصنا\nياللي صليبك سر حياتنا\nنصلي لعملك كرسنا\nواجعلنا الكنز اواني\n\nق) عصر النهضة راجع تاني\nاهتفي يا كنيسة بأغاني\nخلوا الزيت مالي المصابيح\nضُم ايمانك ويا ايماني"}, {"id": "pp097", "cat": "pp", "title": "علطول بحضر", "text": "1- علطول بحضر كل عشية\nوبجهز نفسي للقداس\nاصلي وانام واصحى من بدري\nاستنى صوت الاجراس\n\nلما صوت الجرس يرن\nانزل من بيتي وانا فرحان\nفي الطريق اقرأ مزاميري\nوجوايا حاسس بأمان\n\nق) بحب كنيستي جداً جداً\nوهي ليَّ ام وبيت\nما انا من صغري فيها متربي\n(وعلى احترامها اتربيت) 2\n\n2- لما اوصل كنيستي اسجد\nقدام المذبح واصلي\nامسك ستر الهيكل ابوسه\nمتعود على كدة تملي\n\nاقف بهدوء وبكل ذوق\nلا اتكلم ولا صوتي اعلي\nاصل يسوع حاضر وسطينا\n(والإنجيل وصاني وقاللي) 2\n\nق) بحب كنيستي جداً جداً\nوهي ليَّ ام وبيت\nما انا من صغري فيها متربي\n(وعلى احترامها اتربيت) 2\n\n3- بيت الرب ده كله قداسة\nلازم فيه نكون هاديين\nبابا يسوع يفرح قوي بينا\nلما نكون اولاد شاطرين\n\nاتناول واطلع على فصلي\nبهدوء من غير اي كلام\nاسمع درسي واحفظ ايتي\n(وارجع على بيتي بسلام) 2 \n\nق) بحب كنيستي جداً جداً\nوهي ليَّ ام وبيت\nما انا من صغري فيها متربي\n(وعلى احترامها اتربيت) 2"}, {"id": "pp098", "cat": "pp", "title": "على البير لقاني", "text": "1- على البير لقاني\nمحتار هداني\nعطشان رواني\nيسوع فاديَّ\n\nق) انا لحبيبي\nوحبيبي لي\nطهر لي قلبي\nونور عيني\n\n2- وحُبه رايا\nفيه الكفاية\nاشوف سمايا\nفي رضاه عليا\n\nق) انا لحبيبي\nوحبيبي لي\nطهر لي قلبي\nونور عيني\n\n3- عصاه معايا\nويوم بُكايا\nيسوع عزايا\nوكأس ريا\n\nق) انا لحبيبي\nوحبيبي لي\nطهر لي قلبي\nونور عيني\n\n4- يشبع فؤادي\nما هو زادي\nاطوف وانادي\nخادم فاديَّ\n\nق) انا لحبيبي\nوحبيبي لي\nطهر لي قلبي\nونور عيني\n\n5- ده الروح لروحي\nبلسم جروحي\nيا غربة روحي\nسمائه جاية\n\nق) انا لحبيبي\nوحبيبي لي\nطهر لي قلبي\nونور عيني\n\n6- يا ناس تعالوا\nحالاً تنالوا\nفرحة خلاصه\nدي مجانية\n\nق) انا لحبيبي\nوحبيبي لي\nطهر لي قلبي\nونور عيني"}, {"id": "pp099", "cat": "pp", "title": "على حُسن حُبَّك", "text": "1- على حُسن حُبك الأبوي\nوالرحمة اللي دامت ليَّ\nعليك اتكالي وسندي\nوضمان السماء والأبدية\n\nبفداك ودماك\nمن نهر النعمة بتسقيني\nومعاك ووراك\nاخترت طريقك قويني\n\n2- على حُسن النعمة اللي اتفاضلت\nوجرس رن في وداني\nخطيت الخطوة اللي ابتدأت\nبتوبة قلبي وايماني\n\nوانا راجع وانا سامع\nصوتك عمَّال يناديني\nرحت اجري بعمري\nجوة سترك خبيني\n\n3- على حُسن دمك الغالي\nاللي غفرلي كل خطية\nبصلي ليك وبيحلالي\nاهتف وفرح بحرية\n\nما دُقتك وعرفتك\nويابخت قلبي وسنيني\nأهو غنى واتهنى\nوالفضل ليك يا شاريني\n\nعلى حُسن الوعد المكتوب\nماضيَّ يشهد لأمانتك\nبصليبك انا خوفي مشطوب\nانا كل حياتي سلمتك\n\nبيك غالب وبحارب\nوملاكك حولي ينجيني\nمش خايف وانا واقف\nشايف خلاصك ده بعيني"}, {"id": "pp100", "cat": "pp", "title": "عمري ما يشغل قلبي", "text": "ق) عمري ما يشغل قلبي غيرك\nانتي يا مريم يا ام النور\nده انتي شفيعتي وانتي حبيبتي\nوانتي الملجأ لينا على طول\n\n1- اشكر ربي يسوع الفادي\nإن أنا ابنك يا ام النور\nده انتي رجايا وانتي مُنايا\nوبصلاتك انا مسنود\n\nق) عمري ما يشغل قلبي غيرك\nانتي يا مريم يا ام النور\nده انتي شفيعتي وانتي حبيبتي\nوانتي الملجأ لينا على طول\n\n2- انا مطمن ماسك ايدك\nعمري ما اخاف من اي حروب\nعلشان كدة مش افكر ابداً\nابعد عنك مهما يكون\n\nق) عمري ما يشغل قلبي غيرك\nانتي يا مريم يا ام النور\nده انتي شفيعتي وانتي حبيبتي\nوانتي الملجأ لينا على طول\n\n3- ده انا في قربك باخد بركة\nوقلبي يتملي بالنور\nوامام صورتك انور شمعة\nوارنم ليكي واقول\n\nق) عمري ما يشغل قلبي غيرك\nانتي يا مريم يا ام النور\nده انتي شفيعتي وانتي حبيبتي\nوانتي الملجأ لينا على طول\n\n4- طوباكي انتي يا مريم\nيا عصا موسى وسلم يعقوب\nليكي السلام في كل زمان\nيا شورية ذهب في يد هارون\n\nق) عمري ما يشغل قلبي غيرك\nانتي يا مريم يا ام النور\nده انتي شفيعتي وانتي حبيبتي\nوانتي الملجأ لينا على طول\n\n5- انتي يا امي شفيعة قوية\nفي السما لينا امام يسوع\nتطلبي عنا من فادينا\nيغفر لينا كل الذنوب\n\nق) عمري ما يشغل قلبي غيرك\nانتي يا مريم يا ام النور\nده انتي شفيعتي وانتي حبيبتي\nوانتي الملجأ لينا على طول"}, {"id": "pp101", "cat": "pp", "title": "عند اقدام المحبة", "text": "1- عند اقدام المحبة \nهناك عند الصليب\nموضع خلاصنا\nيسوع الحبيب\nأأتي وانحني قدام الغني\n(انا الفقير)2\n\nق) سواقيه مليانة\nمن ماء حي\nحبه اغنانا\nعن كل شئ\n\n2- عند الطبيب الحقيقي\nالذي احبنا\nالذي وعد ان يشفي\nامراضنا\nأأتي لحبيبي أأتي لطبيبي\n(انا المريض)2\n\nق) سواقيه مليانة\nمن ماء حي\nحبه اغنانا\nعن كل شئ\n\n3- عند محب الخطاة\nوأولهم انا\nعند ذا الباب المفتوح\nقدامنا\nالآن أدخلني بالدم اغسلني\n(انا الشرير)2\n\nق) سواقيه مليانة\nمن ماء حي\nحبه اغنانا\nعن كل شئ\n\n4- عند الألصق من الأخ\nعند محبوبي العجيب\nعند سامع الصلاة\nإذ يسمع ويستجيب\nإليك طلبتي إليك صرختي\n(انا المسكين)2\n\nق) سواقيه مليانة\nمن ماء حي\nحبه اغنانا\nعن كل شئ\n\n5- عند من يسهر عليَّ\nلا ينعس ولا ينام\nعند مخلصي وفاديَّ\nرئيس السلام\nامنحني السلام إلى التمام\n(انا المُهان)2\n\nق) سواقيه مليانة\nمن ماء حي\nحبه اغنانا\nعن كل شئ\n\n6- عند صانع الخيرات\nالرحوم الله\nالذي يمشي معي\nكل الطريق ما احلاه\nاسمع تسبحتي اقبل ذبيحتي\n(انا الحقير)2\n\nق) سواقيه مليانة\nمن ماء حي\nحبه اغنانا\nعن كل شئ\n\n7- عند المحب المعز\nإله الرأفات\nعند من وعد \nأن ينجي من كل الضيقات\nأأتي بضيقتي أأتي لصخرتي\n(انا المحتاج)2\n\nق) سواقيه مليانة\nمن ماء حي\nحبه اغنانا\nعن كل شئ"}, {"id": "pp102", "cat": "pp", "title": "عندك حق", "text": "ق) عندك حق وقصدك خير\nللبائس في وسط الضيق\nبرج حصين ملجأ م السيل\nدي حقايق من غير تلفيق\n\n1- ما انت امين ومابتسمحشي\nبالتجربة غير لو للخير\nعارفينك مابتستحملشي\nتشوف اولادك تحت النير\n\nق) عندك حق وقصدك خير\nللبائس في وسط الضيق\nبرج حصين ملجأ م السيل\nدي حقايق من غير تلفيق\n\n2- اسمك وحدك برج العابد\nيرقد إليك الصديق\nعلى صخرك انا هفضل ثابت\nوعدك مضمون التحقيق\n\nق) عندك حق وقصدك خير\nللبائس في وسط الضيق\nبرج حصين ملجأ م السيل\nدي حقايق من غير تلفيق\n\n3- في وسطنا قائم جبار\nتحمي اولادك ليل ونهار\nوجهك يشرق بالانوار\nوتفجر كل الانهار\n\nق) عندك حق وقصدك خير\nللبائس في وسط الضيق\nبرج حصين ملجأ م السيل\nدي حقايق من غير تلفيق\n\n4- نزلت المرتفعين\nورفعت المتضعين\nاشبعت الجياع خيرات\nوصرفت الاغنياء فارغين\n\nق) عندك حق وقصدك خير\nللبائس في وسط الضيق\nبرج حصين ملجأ م السيل\nدي حقايق من غير تلفيق\n\n5- قالوا عنك حجر إمتحان\nوطوباه للي يآمن بيك\nاتأسست تدي الآمان\nولا يوم يخزى منتظريك\n\nق) عندك حق وقصدك خير\nللبائس في وسط الضيق\nبرج حصين ملجأ م السيل\nدي حقايق من غير تلفيق\n\n6- انت الرب القاضي العادل\nوحدك في ايديك السلطان\nوقضيب مُلكك استقامة\nعرشك فوق كل الأكوان\n\nق) عندك حق وقصدك خير\nللبائس في وسط الضيق\nبرج حصين ملجأ م السيل\nدي حقايق من غير تلفيق\n\n7- مرة تشق قصادنا البحر\nومرة تكون وسطينا في النار\nاحكامك ابعد م الفحص\nطرقك عارفينها الابرار\n\nق) عندك حق وقصدك خير\nللبائس في وسط الضيق\nبرج حصين ملجأ م السيل\nدي حقايق من غير تلفيق"}, {"id": "pp103", "cat": "pp", "title": "في السما انا ليَّ تيجان", "text": "1- في السماء انا ليَّ تيجان\nوكمان هأعيش فرحان\nواتمتع بالحنَّان\nيا عزي بيه هناك\n\nق) \n(يا عزي بيه يا فرحي بيه) 2\nيا عزي بيه هناك\n\n2- في السماء هشوف يسوع\nويمسح الدموع\nلا يكون عطش ولا جوع\nيا عزي بيه هناك\n\nق) \n(يا عزي بيه يا فرحي بيه) 2\nيا عزي بيه هناك\n\n3- في السماء مع الحبيب\nلا يكون هناك نحيب\nوالعز والترحيب\nيا عزي بيه هناك\n\nق) \n(يا عزي بيه يا فرحي بيه) 2\nيا عزي بيه هناك\n\n4- في السماء هأرى الاقداس\nواشوف حبيب الناس\nومفيش هناك نعاس\nيا عزي بيه هناك\n\nق) \n(يا عزي بيه يا فرحي بيه) 2\nيا عزي بيه هناك"}, {"id": "pp104", "cat": "pp", "title": "في انتظار العيد", "text": "1- في انتظار العيد\nوتم المواعيد\nونشوفك حبيبنا\nفي اليوم المجيد\n\nق) بنعد الثواني\nامتى هاتيجي تاني\nكلنا في انتظارك\nبهتاف واغاني\n\n2- جاي على السحاب\nفي موكب مهاب\nملايكة وقديسين\nوالمشهد خلاب\n\nق) بنعد الثواني\nامتى هاتيجي تاني\nكلنا في انتظارك\nبهتاف واغاني\n\n3- عروس المسيح\nخدت المصابيح\nواشواقنا في قلوبنا\nبتسابق الريح\n\nق) بنعد الثواني\nامتى هاتيجي تاني\nكلنا في انتظارك\nبهتاف واغاني\n\n4- والزيت في الاواني\nدي فرحة رباني\nفرح في انتظارك\nيا عريسنا الروحاني\n\nق) بنعد الثواني\nامتى هاتيجي تاني\nكلنا في انتظارك\nبهتاف واغاني\n\n5- هاتيجي وتاخدني\nونبتدي عيدنا\nعيد وابدية\nمع ابويا وسيدنا\n\nق) بنعد الثواني\nامتى هاتيجي تاني\nكلنا في انتظارك\nبهتاف واغاني"}, {"id": "pp105", "cat": "pp", "title": "في ظل حبيبي اشتهيت الجلوس", "text": "1- في ظل حبيبي اشتهيت الجلوس\nمريح التعابى معزي النفوس\nعريس لقلبي فأني عروس\nأنا لحبيبي وحبيبي لي\n\n2- قلب يحن بروح عطوف\nقلب لشخص قريب رؤوف\nقلب صديق حبيب أليف\nأنا لحبيبي وحبيبي لي\n\n3- شخص الحبيب يسوع المسيح\nفيه دواء لكل جريح\nفيه إحتواء لكل طريق \nأنا لحبيبي وحبيبي لي\n\n4- تراني عند اقدام المسيح\nسعيد كأني في قصر فسيح\nفأصغي لصوته كي استريح\nأنا لحبيبي وحبيبي لي"}, {"id": "pp106", "cat": "pp", "title": "في مراعي خضرة", "text": "1- في مراعي خضرة إسكني\nفي مراعي خضرة\nجسدك ودمك يا إلهي\nحقيقة وذكرى\n(أمين امين تي ناهتي آمين اؤمن) 2\n\n2- من ماء الراحة اسقيني\nوارويني وداعة\nوصليبك وحده يحميني\nيعلمني الطاعة\n(أمين امين تي ناهتي آمين اؤمن) 2\n\n3- اديني يا رب حسب قلبي\nاحميني بقدسك\nواهديني لبرك من حبي\nومن أجل اسمك\n(أمين امين تي ناهتي آمين اؤمن) 2\n\n4- وان حاطوا بي اعدائي\nصورتك قدامي\nوانت يا يسوع انت عزائي\nتنور ايامي\n(أمين امين تي ناهتي آمين اؤمن) 2\n\n5- في جميع اوقاتي ويايا\nوالبركة في بيتي\nوبطول ايامي انت معايا\nالدهر الآتي\n(أمين امين تي ناهتي آمين اؤمن) 2"}, {"id": "pp107", "cat": "pp", "title": "فيها خير", "text": "1- فيها خير وإن حتى طالت\nوإن توانت منتظرها\nفي قلبي صلوة واتقالت\nدي اكيد جاية في ميعادها\n\nق) فيها خير اكيد وعارف\nمن بعد صبر السنين\nوتعويض سماوي شايف\nواثق فيك انت الامين\n\n2- فيها خير وإن كتر الظلم\nوالحمل زاد وانحنيت\nخاضع ليه سلمت الأمر\nوبعدها وانصافه رضيت\n\nق) فيها خير اكيد وعارف\nمن بعد صبر السنين\nوتعويض سماوي شايف\nواثق فيك انت الامين\n\n3- فيها خير وإن كان فيه ضيق\nاتكالي كله عليه\nها يقودني طول الطريق\nإلى رحب لا حصر فيه\n\nق) فيها خير اكيد وعارف\nمن بعد صبر السنين\nوتعويض سماوي شايف\nواثق فيك انت الامين\n\n4- فيها خير وإن خاب املنا\nليه مخارج وسط الموت\nيمحي خوفنا ويحيي رجانا\nويشجعنا بأحلى صوت\n\nق) فيها خير اكيد وعارف\nمن بعد صبر السنين\nوتعويض سماوي شايف\nواثق فيك انت الامين"}, {"id": "pp108", "cat": "pp", "title": "قام المسيح", "text": "1- قام المسيح\n والنور في قبره\nشهادة حية على قيامته\nطول العصور\n\nقام المسيح\nوبيه هنقوم وهنحيا معه\nفي الابدية\nفي اخر الدهور\n\nقام المسيح\nوانتصر على الموت والالام\nقام المسيح من الاموات\nافرحوا يا كل الامم\n\nق) سبحوه مجدوه وزيدوه علواً إلى الآبد رحمته.\nفهو المُسَبَّح والمُمَجَد والمتعالي على الأدهار وإلى الآبد رحمته. \n\n2- قام المسيح\n ولو مكان قام من الموت كانت الكرازة باطلة\n\nلكن الآن قام المسيح وصار باكورة الراقدين من أجلنا.\n\nقام المسيح\nوقهر قوات الظلام\nقام المسيح من الاموات\nسبحوه يا كل الامم\n\nق) سبحوه مجدوه وزيدوه علواً إلى الآبد رحمته.\nفهو المُسَبَّح والمُمَجَد والمتعالي على الأدهار وإلى الآبد رحمته. \n\n3- قام المسيح\n وبعد ما لبسنا الفساد  ها ناخد اجسام روحية\n\nها نخلع صورة التراب ويلبسنا صورته النورانية السمائية\n\nقام المسيح\nولأنه قام هو اللي يدين\nجلس في السماء عن اليمين يشفع في كل المؤمنين\n\nق) سبحوه مجدوه وزيدوه علواً إلى الآبد رحمته.\nفهو المُسَبَّح والمُمَجَد والمتعالي على الأدهار وإلى الآبد رحمته. \n\n4- قام المسيح\n ونزل اقسام الأرض السفلي وأصعد معاه قديسيه\n\nانكسرت شوكة الموت والهاوية وفتح الباب وسبى اللي كانوا منتظريه\n\nقام المسيح\nوظهر للتلاميذ مجتمعين\nقام الأمين شاهد أمين صادق قدوس القديسين\n\nق) سبحوه مجدوه وزيدوه علواً إلى الآبد رحمته.\nفهو المُسَبَّح والمُمَجَد والمتعالي على الأدهار وإلى الآبد رحمته. \n\n5- قام المسيح\n وقام وعاش علشان يسود على الكل الاحياء والاموات\n\nوها تجثوا لأسمه كل ركبة فوق الارض وتحت الارض وفي السموات\n\nقام المسيح\nوإترفع عنا حكم الموت\nقام اللي ليه كل الإكرام والمجد ليه وحده السجود\n\nق) سبحوه مجدوه وزيدوه علواً إلى الآبد رحمته.\nفهو المُسَبَّح والمُمَجَد والمتعالي على الأدهار وإلى الآبد رحمته. \n\n6- قام المسيح\n وبعد ما راح وكرز للأرواح المسجونة في الجحيم\n\nولما شافوه القديسين فرحوا بمجيئه وخرجوا في ايده للنعيم\n\nقام المسيح\nوليه ها نعيش كل الايام\nلا نحيا بعد لأنفسنا بل للذي من اجلنا مات وقام\n\nق) سبحوه مجدوه وزيدوه علواً إلى الآبد رحمته.\nفهو المُسَبَّح والمُمَجَد والمتعالي على الأدهار وإلى الآبد رحمته. "}, {"id": "pp109", "cat": "pp", "title": "قطعت صلتي بالعالم", "text": "1- قطعت صلتي بالعالم الفاني \nوسلمت قلبي لمن \n(مات واحياني) 2\n\nق) (أفوز بالاكاليل) 2\nمهما عملت يا شيطان\n(رجوعي مستحيل) 2\n\n2- حارب واعمل جهدك\nوصوب السهام\nلكنني بقوة يسوع\n(غالب على الدوام) 2\n\nق) (أفوز بالاكاليل) 2\nمهما عملت يا شيطان\n(رجوعي مستحيل) 2\n\n3- جملي في العالم\nوزينه ليا\nلكنني عالم تمام\n(فكرك فكر الحية) 2\n\nق) (أفوز بالاكاليل) 2\nمهما عملت يا شيطان\n(رجوعي مستحيل) 2\n\n4- قرب مجئ يسوع\nوتنتهي الحروب\nفأسهر يا مؤمن وانتصر\n(اوعى تكون مغلوب) 2\n\nق) (أفوز بالاكاليل) 2\nمهما عملت يا شيطان\n(رجوعي مستحيل) 2"}, {"id": "pp110", "cat": "pp", "title": "قلبي بيفرح", "text": "1- (قلبي بيفرح لمَّا بيسمع صوت فادينا)2\nلمَّا بيحضر في وسطينا بيعزينا\n\nق) \n(صوت يسوع الحلو دايماً بيعزينا)\n\n2- (لمَّا نصلي لمَّا نجاهد لمَّا نرنم)2\nروح الله يرشد ويبارك ويعلم\n\nق) \n(صوت يسوع الحلو دايماً بيعزينا)\n\n3- (نغلب إبليس وجنوده وسهامه)2\nلمَّا نكون حاملين كتابه ونقرا كلامه\n\nق) \n(صوت يسوع الحلو دايماً بيعزينا)\n\n4- (لو دخلنا العُمق هنشاهد جماله)2 \nوالرياح تخضع له وتكون له مطيعة \n\nق) \n(صوت يسوع الحلو دايماً بيعزينا)\n\n5- (صوت يسوع أحيا لعازر بعد موته)2\nأخرجه بالأمر وبسلطان لاهوته\n\nق) \n(صوت يسوع الحلو دايماً بيعزينا)"}, {"id": "pp111", "cat": "pp", "title": "قوموا افرحوا", "text": "1- قوموا ارفعوا علم الصليب\nوبشروا الخطاة\nومجدوا اسم المسيح\nوسبحوا الإله\nالمجد لك يا رب\n يارب لك المجد\n\nق) امتى نحمله يا ابويا\nامتى نوصل انا مشتاقلك\nامتى ندخل\nلدار المجد\n\n2- هناك مفيش نهاية\nولا هناك زمان\nبل سعادة ابدية\nخالية من الاحزان\n\nق) امتى نحمله يا ابويا\nامتى نوصل انا مشتاقلك\nامتى ندخل\nلدار المجد\n\n3- هناك مافيش دموع\nولا عطش ولا جوع\nبل فرح مجيد وسلام\nلحبيب القلب يسوع\n\nق) امتى نحمله يا ابويا\nامتى نوصل انا مشتاقلك\nامتى ندخل\nلدار المجد\n\n4- فيها حبيب القلب ملكنا المنصور\nفيها لنا السلام والعز والسرور\nدموعنا التي هنا ذرفناها\nيمسحها لنا يسوع بالحب لنا\n\nق) امتى نحمله يا ابويا\nامتى نوصل انا مشتاقلك\nامتى ندخل\nلدار المجد\n\n5- يخطفنا من دار الشقاء\nإلى دار الفردوس\nارض المدينة ذهب\nوعلى الذهب هاندوس\nونعيش في بيت الآب\nحول العرش العظيم\nحسب وعد المسيح\nالصادق الأمين\n\nق) امتى نحمله يا ابويا\nامتى نوصل انا مشتاقلك\nامتى ندخل\nلدار المجد"}, {"id": "pp112", "cat": "pp", "title": "كتر اغانيك", "text": "1- كتر اغانيك يا مسافر. احنا في ترحال. شد الاوتار للصابر. خليه متشال. خلي الاشواق شغالة. والروح شغال. يسند في قلوب الرحالة. ويحيي الابطال. (كتر اغانيك)3 يا مسافر    احنا في ترحال\n\n2- كتر اغانيك يا مهلل. بكلام الله. واغني الالحان من نغمة هلليلويا. اضبط وترك على اصوات الروح في المكتوب. وحد نغمك مع نغمات الشعب المحبوب. (كتر اغانيك)3 يا مهلل بكلام الله\n\n3- كتر اغانيك واتكلم. اخزي الشياطين. الغنا يصفعهم ويجبهم عند القدمين. ضرب الاوتار والسقفة وبوق الفارحين. هتف الابرار والكفة عليت بآمين. (كتر اغانيك)3 واخزي الشياطين\n\n4- كتر اغانيك يا معلي صوت الإيمان. يملاك الروح اللي محلي حب الفرحان. ما احلى التجميع اللي مخلي كل الأخوان. رافعين اسماء المتجلي في طيب العرفان. (كتر اغانيك)3 يا معلي صوت الإيمان\n\n5- كتر اغانيك طولها وقول عنه كتير. بالذكر تقصر ايامها ويحلى المسير. بتهون الغربة واتعابها لحظة ما نطير. من عتمتها ومن آلامتها لوجه المنير. (كتر اغانيك)3 طولها وقول عنه كتير\n\n6- كتر اغانيك قول هانت جاي ابن الله. اصرخ صحي في قلوب نامت وهي منتظراه. طوباه الساهر والثابت مستني لقاه. ويومين ويعدوا وفي الثالث هنكون معاه. (كتر اغانيك)3 قول هانت جاي ابن الله"}, {"id": "pp113", "cat": "pp", "title": "كلام الإله", "text": "1- كلام الإله ، غذاء القلوب\nيقدس نفسي ، ويحيي الفؤاد\nيزيل الهموم ، ويعطي العزاء\nلذيذ لدينا ، كقطر الشهاد\n\n2- دواء ثمين ، لكل الكروم\nوسيف ثقيل ، لوقت الجهاد\nكنار يبيد ، جميع الشرور\nوترس قوي ، لنا في النضال\n\n3- سراج مضئ ، ينير الظلام\nويهدي الخُطى ، في إجتياز الطريق\nيقود النفوس ، لطريق السلام\nدليل امين ، كأوفى رفيق\n\n4- يعزي الحزين ، يزيح العناء\nويعطي السلام ، ويولي النجاة\nيفيض الامان ، ويهدي العزاء\nطعام جليل ، غذاء الحياة\n\n5- خزانة مجد ، وكنز ثمين\nوفيه وعود ، وعهد الحبيب\nوكرم شهي ، لذيذ الثمار\nجميل بهيج ، كمرعى خصيب\n\n6- وفيه الخلاص ، كنهر يفيض\nسلاماً وبراً ، لنيل الكمال\nبشارة خير ، ونبع السرور\nعلاقة حُب ، وتاج الجمال\n\n7- تزول السماء ، وكل الجبال\nوقوله يبقى ، وليس يحول\nوعود الإله ، تماماً تدوم\nفلا من كلامه ، حرف يزول"}, {"id": "pp114", "cat": "pp", "title": "كلامك يا يسوع", "text": "1- كلامك يا يسوع\nده كلام غالي وثمين\nنتمتع بيه وأحنا وياك\n(بنقرا في الإنجيل) 2\n\nق) كلام الله غالي\nكنزي وراس مالي\nبيعزي قلبي ويحميني\n(ويقدس أيامي) 2\n\n2- كلامك يا يسوع\nدواء للمُتْعَبينْ\nيشفي ويسند ويشدد\n(جميع المحتاجين) 2\n\nق) كلام الله غالي\nكنزي وراس مالي\nبيعزي قلبي ويحميني\n(ويقدس أيامي) 2\n\n3- كلامك يا يسوع\nسيف يغلب الأشرار\nترس وحصن لينا قوي\n(في الحرب والجهاد) 2\n\nق) كلام الله غالي\nكنزي وراس مالي\nبيعزي قلبي ويحميني\n(ويقدس أيامي) 2\n\n4- كلامك يا يسوع\nسراج يضيء الظلام\nيهدي كل خاطئ بعيد\n(إلى طريق الخلاص) 2\n\nق) كلام الله غالي\nكنزي وراس مالي\nبيعزي قلبي ويحميني\n(ويقدس أيامي) 2\n\n5- كلامك يا يسوع\nدليل مرشد وأمين\nلكل مَنْ ضل وتاه\n(بعيد عن المسيح) 2\n\nق) كلام الله غالي\nكنزي وراس مالي\nبيعزي قلبي ويحميني\n(ويقدس أيامي) 2\n\n6- كلامك يا يسوع\nعزاء لكل حزين\nيشبع ويروي القلوب\n(اللي ملكك يا قدير) 2\n\nق) كلام الله غالي\nكنزي وراس مالي\nبيعزي قلبي ويحميني\n(ويقدس أيامي) 2\n\n7- كلامك يا يسوع\nده كنز غالي وثمين\nمليان وعود وبيطمن\n(جموع الخائفين) 2\n\nق) كلام الله غالي\nكنزي وراس مالي\nبيعزي قلبي ويحميني\n(ويقدس أيامي) 2\n\n8- كلامك يا يسوع\nده نهر فايض غزير\nمليان نعمة وبركات وسلام\n(وثمار ملهاش مثيل) 2\n\nق) كلام الله غالي\nكنزي وراس مالي\nبيعزي قلبي ويحميني\n(ويقدس أيامي) 2\n\n9- كلامك يا يسوع\nبيرجع الضالين\nوبشارة تفرح القلوب\n(وتغير الخاطئين) 2\n\nق) كلام الله غالي\nكنزي وراس مالي\nبيعزي قلبي ويحميني\n(ويقدس أيامي) 2\n\n10- كلامك يا يسوع\nتاج وأكليل على راسي\nنفتخر بيه كل الزمان\n(ده أعظم ميراثي) 2\n\nق) كلام الله غالي\nكنزي وراس مالي\nبيعزي قلبي ويحميني\n(ويقدس أيامي) 2\n\n11- كلامك يا يسوع\nولا حرف منه يزول\nثابت وراسخ مثل الجبال\n(وقوته بركة تدوم) 2\n\nق) كلام الله غالي\nكنزي وراس مالي\nبيعزي قلبي ويحميني\n(ويقدس أيامي) 2\n\n12- كلامك يا يسوع\nده روح لينا وحياة\nحصن حصين لينا دايماً\n(في غربة الحياة) 2\n\nق) كلام الله غالي\nكنزي وراس مالي\nبيعزي قلبي ويحميني\n(ويقدس أيامي) 2\n\n13- كلامك يا يسوع\nلينا حماية ونجاة\nيحفظ ويبارك ويعلم\n(أولادك كل الأيام) 2\n\nق) كلام الله غالي\nكنزي وراس مالي\nبيعزي قلبي ويحميني\n(ويقدس أيامي) 2\n\n14- كلامك يا يسوع\nلينا اوفى صديق أمين\nملجأ ومين وسند\n(لكل مَنْ في ضيق) 2\n\nق) كلام الله غالي\nكنزي وراس مالي\nبيعزي قلبي ويحميني\n(ويقدس أيامي) 2\n\n15- كلامك يا يسوع\nغذاء للروح والجسد\nيشبع ويروي كل عطشان\n(مشتاق لرب المجد) 2\n\nق) كلام الله غالي\nكنزي وراس مالي\nبيعزي قلبي ويحميني\n(ويقدس أيامي) 2\n\n16- كلامك يا يسوع\nينبوع للفضائل\nوروحك القدوس يعمل\n(يملأ الأواني ثمار) 2\n\nق) كلام الله غالي\nكنزي وراس مالي\nبيعزي قلبي ويحميني\n(ويقدس أيامي) 2"}, {"id": "pp115", "cat": "pp", "title": "كلمة في ودنك", "text": "ق) كلمة في ودنك انت يا خادم\nياللي بقيت ضمن الخدام\nتعرف ايه عن معنى الخدمة\nولا الخدمة دي بس كلام\n\n1- معنى الخدمة تنكر ذاتك\nعشان الله يظهر قدام\nولا مُصِّر انك تظهر\nوتخفي يسوع انت وتبان\nقبل ما تخدم غيرك لازم\nتخدم نفسك انت كمان\n\nق) كلمة في ودنك انت يا خادم\nياللي بقيت ضمن الخدام\nتعرف ايه عن معنى الخدمة\nولا الخدمة دي بس كلام\n\n2- مش مطلوب تخرج شياطين\nولا مفسر للأحلام\nلكن تبقى انجيل مفتوح\nمكان ما تحل يحل سلام\nقبل ما تخدم غيرك لازم\nتخدم نفسك انت كمان\n\nق) كلمة في ودنك انت يا خادم\nياللي بقيت ضمن الخدام\nتعرف ايه عن معنى الخدمة\nولا الخدمة دي بس كلام\n\n3- أصل الخادم اصله سفير\nملاك في الارض صورة انسان\nبلاش تعمل عمل برخاوة\nعيش خادم بعيون لا تنام\nقبل ما تخدم غيرك لازم\nتخدم نفسك انت كمان\n\nق) كلمة في ودنك انت يا خادم\nياللي بقيت ضمن الخدام\nتعرف ايه عن معنى الخدمة\nولا الخدمة دي بس كلام\n\n4- عملك تنمو مثل الحنطة\nمش عملك تخلع في زوان\nكن متواضع زي مسيحك\nغسل ارجل تلاميذه زمان\nقبل ما تخدم غيرك لازم\nتخدم نفسك انت كمان\n\nق) كلمة في ودنك انت يا خادم\nياللي بقيت ضمن الخدام\nتعرف ايه عن معنى الخدمة\nولا الخدمة دي بس كلام\n\n5- اقولك تاني ولا كفاية\nاصحى وفوق من الأوهام\nكونك خادم فأنت مُطالب\nبدماء غيرك وانت كمان\nقبل ما تخدم غيرك لازم\nتخدم نفسك انت كمان\n\nق) كلمة في ودنك انت يا خادم\nياللي بقيت ضمن الخدام\nتعرف ايه عن معنى الخدمة\nولا الخدمة دي بس كلام"}, {"id": "pp116", "cat": "pp", "title": "كلمة يا ربي", "text": "1- كلمة يا ربي ونفسي أحكيها\nعن اتعابي انت قاريها\nعن آلامي وضعفي احكيلك\nعن آثامي نفسي اشكيلك\nكلمة آه يا ربي. كلمة آه ده جرمي 2\n\n2- ربي يسوع مصلوب علشاني\nلب ندائي حبه الرياني\nبيقولي ارجع لي من تاني\nارجع يا ابني لأحضاني\nكلمة آه يا ربي. كلمة آه ده جرمي 2\n\n3- وعد يا ربي وقلبي تاب\nعن خطية وجرم عناد\nعن شهوات العالم ضعفي\nعن خطيتي وذنبي\nكلمة آه يا ربي. كلمة آه ده جرمي 2"}, {"id": "pp117", "cat": "pp", "title": "كنت في الطريق", "text": "1- كنت في طريقي تائها مسكين\nعبداً لأبليس دائماً حزين\nرآني يسوع اذرف الدموع\nترك السماء لينقذني 2\n\nق) يسوع منيتي منه تعزيتي\n له محبتي مجداً لأسمه\nيسوع صخرتي ومنه قوتي\nسلمته قلبي الليلويا\n\n2- فزعت صرخت من هول الظلام\nفقدت رجائي ايضاً لا سلام\nرآني الحبيب في أسر رهيب\nترك السماء لينقذني 2\n\nق) يسوع منيتي منه تعزيتي\n له محبتي مجداً لأسمه\nيسوع صخرتي ومنه قوتي\nسلمته قلبي الليلويا\n\n3- بغتة رأيت نوراً في الطريق\nيسوع ناداني بصوت رقيق\nقال لا انساك نعمتي ترعاك\nلا تخاف شراً ما دُمتُ معاك 2\n\nق) يسوع منيتي منه تعزيتي\n له محبتي مجداً لأسمه\nيسوع صخرتي ومنه قوتي\nسلمته قلبي الليلويا\n\n4- ها انا يا ربي اعطيك قلبي\nقصدك اتمم ولو للصلب\nاوثق مع بولس اهتف مع داود\nالليلويا مجداً واغلب مع يسوع 2\n\nق) يسوع منيتي منه تعزيتي\n له محبتي مجداً لأسمه\nيسوع صخرتي ومنه قوتي\nسلمته قلبي الليلويا"}, {"id": "pp118", "cat": "pp", "title": "كنيستي ارجو لكِ", "text": "1- كنيستي ارجو لكي\nمن عزة الإله\nخلاص كل الشعب\nيا سفينة النجاة\n\nق) عُد يا إلهي\nواطلع وانظر من السماء\nتعهد الكرمة\nبالخصب والنماء\n\n2- ليحفظ الرب لكي\nعهداً على الدوام\nوليملأ الإله \nابراجك بالسلام\n\nق) عُد يا إلهي\nواطلع وانظر من السماء\nتعهد الكرمة\nبالخصب والنماء\n\n3- اطلب راحة لكي\nفي قصرك الرحب\nدوماً لأجل إخوتي\nوالأهل والصحب\n\nق) عُد يا إلهي\nواطلع وانظر من السماء\nتعهد الكرمة\nبالخصب والنماء\n\n4- من أجل بيت الله\nاطلب لكي الخيرات\nملتمساً فوزاً لكي\nمن مصدر القوات\n\nق) عُد يا إلهي\nواطلع وانظر من السماء\nتعهد الكرمة\nبالخصب والنماء\n\n5- أنت إلهنا القوي\nالمُنجِد المُعين\nعونك ملجأ لنا\nوحصننا الحصين\n\nق) عُد يا إلهي\nواطلع وانظر من السماء\nتعهد الكرمة\nبالخصب والنماء"}, {"id": "pp119", "cat": "pp", "title": "كون ويانا", "text": "1- كون ويانا، نجينا، قوينا، لينا، إيمان مالينا، انك هنا موجود، خليك طول الوقت معانا، عدينا، للمينا، لينا، كام جرح، داوينا، شعبك بيك مسنود.\n\n2- املأ قلوبنا ايمان دايماً علشان، هو اللي هايرضيك، ايمانا، وبالتأكيد، عايزين اعمالنا، تشهد دايماً ليك، عايزين صورتك دايماً، فينا تبان، شكلنا بإيديك، غيرنا، وارمي بعيد، جميع افكارنا، اللي مهياش فيك.\n\n3- يا رب يا عالم ضعف الإنسان، ضعاف وملناش غير السنة اللي عليك، لجلالك جينا، تسندنا يا رحيم، انت مادد لينا ايدك، بالإحسان، بالحب وبالخير، لو ننده، ليك نلاقيك، تيجي تنجينا، يا إلهنا انت عظيم."}, {"id": "pp120", "cat": "pp", "title": "لا فضة ولا دهب", "text": "1- عبد وتمني وصل\nفلس ولا شاري فصل\nبس هو اشتراني\nبس يسوع اشتراني\n\nق) لا فضة ولا دهب\nمدفوع انا فيَّ\nده الدم اللي انسكب\nده دم فاديَّ\n\n2- انا تراب واتعجن\nبس بقالي تمن\nلما هو اشتراني\nلما يسوع اشتراني\n\nق) لا فضة ولا دهب\nمدفوع انا فيَّ\nده الدم اللي انسكب\nده دم فاديَّ\n\n3- انا الطين واتصنع\nوغليت لما دفع\nالتمن واشتراني\nالتمن واشتراني\n\nق) لا فضة ولا دهب\nمدفوع انا فيَّ\nده الدم اللي انسكب\nده دم فاديَّ\n\n4- انا كنت المزدرى\nلكن بيَّ ارتضى\nوقبلني واشتراني\nيسوع اشتراني\n\nق) لا فضة ولا دهب\nمدفوع انا فيَّ\nده الدم اللي انسكب\nده دم فاديَّ\n\n5- انا كنز ما يتوصف\nمع اني من خزف\nاصل بدمه اشتراني\nاصل يسوع اشتراني\n\nق) لا فضة ولا دهب\nمدفوع انا فيَّ\nده الدم اللي انسكب\nده دم فاديَّ"}, {"id": "pp121", "cat": "pp", "title": "لا هاشكي", "text": "1- لا ها شكي ولا اقول امتى\nالقاضي العادل انت\nوحقي عندك انت\nوبيك كسبان القضية\n\nق) فرِّح قلب عبد اللي اتكل عليك\nاسمع من اجل اسمك صرختي اليك\nالعين بتترجاك والقلب اتمنى رضاك\nومين اللي استناك ومخدش العطية\n\n2- يا رافع راسي وقمتي\nبتدافع عني في صمتي\nبترد ليا كرامتي\nوبتوفي بوعدك ليا\n\nق) فرِّح قلب عبد اللي اتكل عليك\nاسمع من اجل اسمك صرختي اليك\nالعين بتترجاك والقلب اتمنى رضاك\nومين اللي استناك ومخدش العطية\n\n3- طيب وكتيرة امانتك\nانا ماشي في ضل حمايتك\nلولا يا رب عنايتك\nما كان النور في عنيا\n\nق) فرِّح قلب عبد اللي اتكل عليك\nاسمع من اجل اسمك صرختي اليك\nالعين بتترجاك والقلب اتمنى رضاك\nومين اللي استناك ومخدش العطية"}, {"id": "pp122", "cat": "pp", "title": "لأمانته", "text": "1- (لأمانته)2 مشي لحد سوخار قرب الضيعة\n(وفي حبه وفي حبه خلص سامرية كانت ضايعة) 2\n\nق) يا نعمتك اللي تدوب قلبي القاسي\nيا محبتك اللي بتشعل قلبي العاصي 2\n\n2- (شوفوا يوسف)2 \nاخواته باعوه في بلاد تانية\n(شوفوا سيده شوفوا سيده ازاي صنع بيه خير يملا الدنيا)2\n\nق) يا نعمتك اللي تدوب قلبي القاسي\nيا محبتك اللي بتشعل قلبي العاصي 2\n\n3- (شوفوا بطرس)2 \nراح انكر سيده اللي احبه\n(شوفوا سيده شوفوا سيده عمله كارز وشفى نفسه) 2\n\nق) يا نعمتك اللي تدوب قلبي القاسي\nيا محبتك اللي بتشعل قلبي العاصي 2\n\n4- (شوفوا شاول)2 \nكان دايماً يقتل ومفتري\n(بقى بولس بقى بولس يحني الركبتين لأسم العالي) 2\n\nق) يا نعمتك اللي تدوب قلبي القاسي\nيا محبتك اللي بتشعل قلبي العاصي 2\n\n5- (شوفوا ربي)2 \nمن اجلي احتمل آلام الصليب\n(دا حبيبي دا حبيبي يا ناس اللي غفر ذنبي الرهيب) 2\n\nق) يا نعمتك اللي تدوب قلبي القاسي\nيا محبتك اللي بتشعل قلبي العاصي 2"}, {"id": "pp123", "cat": "pp", "title": "لسة الباب مفتوح", "text": "ق) لسة الباب مفتوح\nادخل ياللي بعيد\nلو ضاعت الفرصة \nندمك مش هايفيد\n\n1- اللي هيقفل مش انسان\nممكن تترجاه يفتحلك\nلا ده الرب الديَّان\nايه عذرك ما هو ياما ندهلك\n\nق) لسة الباب مفتوح\nادخل ياللي بعيد\nلو ضاعت الفرصة \nندمك مش هايفيد\n\n2- ياللي غرورك يوم خلاك\nتنسى آلام وجراح وصليب\nحاب اخر البُعد هلاك\nحاسب اخر البُعد لهيب\n\nق) لسة الباب مفتوح\nادخل ياللي بعيد\nلو ضاعت الفرصة \nندمك مش هايفيد\n\n3- عهد النعمة اليوم بينادي\nيللا تعالى يا كل بعيد\nتفرح ويا يسوع الفادي\nوفي الابدية الفرح يزيد\n\nق) لسة الباب مفتوح\nادخل ياللي بعيد\nلو ضاعت الفرصة \nندمك مش هايفيد"}, {"id": "pp124", "cat": "pp", "title": "لمَّا اطلب يسوع", "text": "1- لما اطلب يسوع ألقاه\nدايماً مني قريب\nفي جراحي يداوي ودواه\nمش ممكن يخيب\n\nق) يسوع إلهي يقدر\nوبيعمل معجزات\nولا عنده حاجة صعبة\nولا عنده مستحيلات\n\n2- هو وعدني وقال ادعوني\nحتى في يوم الضيق\nانقذك وانت تمجدني\nواكون لك رفيق\n\nق) يسوع إلهي يقدر\nوبيعمل معجزات\nولا عنده حاجة صعبة\nولا عنده مستحيلات\n\n3- وإن هاجت عليَّ الريح\nهو اللي يهديها\nيحفظني ويقود سفينتي\nعلى البر يرسيها\n\nق) يسوع إلهي يقدر\nوبيعمل معجزات\nولا عنده حاجة صعبة\nولا عنده مستحيلات"}, {"id": "pp125", "cat": "pp", "title": "لمَّا اقولك", "text": "1- لما اقولك مد ايدك\nعلى البحر يا ابني مدها\nاوعى تنظر لحجم ايدك\nبصغرها وبضعفها\n\nايدي القديرة ماسكة ايدك\nاديها قوة وشدها\nونبقى ايد واحدة عظيمة\nتأمر بحور وتشقها\n\n2- لما اقولك اوعى تسجد\nللملك اسمع كلامي\nوصل رسالتي واوعى تسكت\nوسط الاسود هاجي بسلامي\n\nهديك كرامة بين الملوك\nينادوك بأسمي ويهابوك\nويشهدوا بقدرة أبوك\nيسوع القدير ملك الملوك\n\n3- لما جليات يقف قصادك\nوالناس يقولوا مستحيل\nاقف واعلن انتصارك\nواعلن انه في ايدك اسير\n\nانا عارف امكانياتك\nعارف انك راعي صغير\nلكن بقوة اقتداري\nانا هعمل بيك المستحيل\n\n4- لما اقولك ايه اللي في ايدك\nمتقولش يا ابني قليلين\nها اشبع الاف الناس وازيدك\nبخمس ارغفة وسمكتين\n\nها امشي معاك واكون سنيدك\nملجأ وقوة ومعين\nواللي تقول عليه قليل \nهاشبعك بيه طول السنين"}, {"id": "pp126", "cat": "pp", "title": "لمَّا اكون تعبان", "text": "1- (لما اكون تعبان \nأروح لمين غيرك) 2\nأنت اللي تريحني يا يسوع\n(اركع واصليلك) 2\n\n2- (لما اكون حزين \nأروح لمين غيرك) 2\nأنت اللي تعزيني يا يسوع\n(اركع واصليلك) 2\n\n3- (لما اكون عطشان \nأروح لمين غيرك) 2\nأنت اللي ترويني يا يسوع\n(اركع واصليلك) 2\n\n4- (لما اكون مريض \nأروح لمين غيرك) 2\nأنت اللي تشفيني يا يسوع\n(اركع واصليلك) 2\n\n5- (لما اكون حيران \nأروح لمين غيرك) 2\nأنت اللي ترشدني يا يسوع\n(اركع واصليلك) 2\n\n6- (لما اكون في ضيق \nأروح لمين غيرك) 2\nأنت اللي تنقذني يا يسوع\n(اركع واصليلك) 2\n\n7- (لما اكون مظلوم \nأروح لمين غيرك) 2\nأنت اللي تنصفني يا يسوع\n(اركع واصليلك) 2"}, {"id": "pp127", "cat": "pp", "title": "لمَّا الرياح تزيد", "text": "1- لما الرياح تزيد\nوالبحر يبقى عنيد\nالكل يطيع اوامره\nوكمان يخضع لها\n\nق) هايحلها هايحلها\nده إلهي حي ويقدر\n(هو قدها) 2\n\n2- لما الاتون يقيد\nوتحس انك وحيد\nيمشي معاك في النار\nيتمجد وسطها\n\nق) هايحلها هايحلها\nده إلهي حي ويقدر\n(هو قدها) 2\n\n3- لما السهام تزيد\nوإن جاتك من القريب\nهايكون هو بدالك\nوبنفسه يصدها\n\nق) هايحلها هايحلها\nده إلهي حي ويقدر\n(هو قدها) 2\n\n4- وإن عليت الاسوار\nوإن حسيت بإنهيار\nهنلف احنا حواليها\nوبقوة تهدها\n\nق) هايحلها هايحلها\nده إلهي حي ويقدر\n(هو قدها) 2"}, {"id": "pp128", "cat": "pp", "title": "لماذا نحن فقراء", "text": "1- لماذا نحن فقراء\n وإلهنا غني؟\nلماذا نحن ضعفاء\n وإلهنا قوي؟\n\nقوموا نترجاه\nيمنحنا رضاه\nوبغنى النعمة يغنينا\nويحل بروح قدسه فينا\n\nق) باركنا\nاستخدمنا\nوبروح قدسك أيدنا\n\n2- لماذا نحن خائفين\nوإلهنا معانا ؟\nلماذا نحن مرتعبين \nوسلامه اعطانا ؟\n\nهو معانا هو فينا\nهو الماسك بأيدينا\nومحدش يقدر علينا \nأن يخطفنا أو يؤذينا\n\nق) باركنا\nاستخدمنا\nوبروح قدسك أيدنا\n\n3- لماذا نحن مهتمين \nوالمستقبل لينا ؟\nنحن للسماء ذاهبين\nللقاء فادينا\n\nالثياب البيض نلبس\nوالتاج الغالي يهدينا\nويسوع ده وعده لينا\nهايملكنا كراسينا\n\nق) باركنا\nاستخدمنا\nوبروح قدسك أيدنا"}, {"id": "pp129", "cat": "pp", "title": "ليه يا خاطي تعيش", "text": "ق) ليه يا خاطي تعيش وتموت في خطاياك ؟\nوالرب فداك على الصليب\nقدملك منحك اعطاك\nكل شئ يسوع الحبيب\n\n1- صلب بين لصين\nحمل كل الدين\nودفع الحساب \nصلب من اجل ذنبك\nحمل كل الدين عنك\nوفي دفع الحساب\nداق مر العذاب\nتعالى إليه \nباعد عنه ليه 3\n\nق) ليه يا خاطي تعيش وتموت في خطاياك ؟\nوالرب فداك على الصليب\nقدملك منحك اعطاك\nكل شئ يسوع الحبيب\n\n2- يسوع قد فداك\nوبدمه نجاك\nودعاك لسماه\nفداك بالدم الكريم\nنجاك من نار الجحيم\nودعاك لسماه \nلتحيا في حماه\nتعالى إليه\nباعد عنه ليه 3\n\nق) ليه يا خاطي تعيش وتموت في خطاياك ؟\nوالرب فداك على الصليب\nقدملك منحك اعطاك\nكل شئ يسوع الحبيب\n\n3- مات يسوع البار\nرفع عنك العار\nودان الخطية\nمات البار عن الخطاة\nوبموته وهب الحياة\nودان الخطية \nلنحيا في حرية\nتعالى إليه\nباعد عنه ليه 3\n\nق) ليه يا خاطي تعيش وتموت في خطاياك ؟\nوالرب فداك على الصليب\nقدملك منحك اعطاك\nكل شئ يسوع الحبيب"}, {"id": "pp130", "cat": "pp", "title": "م الوباء هو ينجيك", "text": "1- م الوباء هو ينجيك\nتحت جناحه هايحميك\nمن خوف الليل متخافشي وسهم\nيطير مايجيش جنبيك\n\nق) ستر العلي ده عنواني\nوفي ظله ببات طب ايه تاني هاينقصني\nربي ده ملجأي وحصني\nرامي اتكالكي على العالي\nياما فخاخ جه ونصبهالي \nكم صياد لقيت الله جه نجاني\n\n2- هايوصي ملايكته بيك\nيفضلوا دائماً حواليك\nعلى ايديهم يشيلوك\nماتقعش وتخبط في حجر رجليك\n\nق) ستر العلي ده عنواني\nوفي ظله ببات طب ايه تاني هاينقصني\nربي ده ملجأي وحصني\nرامي اتكالكي على العالي\nياما فخاخ جه ونصبهالي \nكم صياد لقيت الله جه نجاني\n\n3- لما تتعلق بيه\nهو ينجيك بإيديه\nوهيستجيب لما هاتدعيه\nفناديه في الضيق تلاقيه\n\nق) ستر العلي ده عنواني\nوفي ظله ببات طب ايه تاني هاينقصني\nربي ده ملجأي وحصني\nرامي اتكالكي على العالي\nياما فخاخ جه ونصبهالي \nكم صياد لقيت الله جه نجاني"}, {"id": "pp131", "cat": "pp", "title": "م ر ي م مريم", "text": "ق) «م ر ي م» مريم اسمك غالي عليَّ\nالـ م مرهم تداويني بشفاعتك ليَّ\nوالـ ر ربنا جه منك يفدي البشرية\nوالـ ي يا سلام على قلبك مليان حنية\nوالـ م تاني مين زيك يا طاهرة نقية\n\n1- الـ م يعني محدش عنده فضايل زيك\nوالـ ر راضية وصابرة وشاكرة اوقات آلمك\nوالـ ي يا معينة إشفعي فيَّ قدام ربك\nوالـ م تاني ملكة علشان ملك السما ابنك\nيا أم النور يا شفيعة في كل البشرية\n\nق) «م ر ي م» مريم اسمك غالي عليَّ\nالـ م مرهم تداويني بشفاعتك ليَّ\nوالـ ر ربنا جه منك يفدي البشرية\nوالـ ي يا سلام على قلبك مليان حنية\nوالـ م تاني مين زيك يا طاهرة نقية\n\n2- الـ م مؤمنة بيسوع وكلامه وإنجيله\nوالـ ر روحك سابحة في سمواته تصليله\nوالـ ي يوم فرحك لمَّا يا عدرا وصلتيله\nوالـ م تاني من صغرك الله عيشتيله\nوأنتي في الهيكل عيشتي في طُهر وروحانية \n\nق) «م ر ي م» مريم اسمك غالي عليَّ\nالـ م مرهم تداويني بشفاعتك ليَّ\nوالـ ر ربنا جه منك يفدي البشرية\nوالـ ي يا سلام على قلبك مليان حنية\nوالـ م تاني مين زيك يا طاهرة نقية\n\n3- الـ م مدحك زي الشهد يا عدرا في فمي\nوالـ ر راحتي تيجي لمَّا تصلي يا أمي\nوالـ ي يأسي بشفاعتك بيزول مع همي\nوالـ م تاني مريم حُبك جوة في دمي\nما انتي شفيعتي وأمي حبيبتي وضي عينيَّ\n\nق) «م ر ي م» مريم اسمك غالي عليَّ\nالـ م مرهم تداويني بشفاعتك ليَّ\nوالـ ر ربنا جه منك يفدي البشرية\nوالـ ي يا سلام على قلبك مليان حنية\nوالـ م تاني مين زيك يا طاهرة نقية"}, {"id": "pp132", "cat": "pp", "title": "ما احلاكي يا مريم", "text": "1- حملتي فادي البشرية\nولدتي خالق الدنيا\nارضعتي رب الدنيا\n(طوباكي يا مريم طوباكي)2 \n\nق) ما احلاكي يا مريم ما احلاكي\nحملتي النور في احشاكي\nاختار جمالك وبهائك\n(طوباكي يا مريم طوباكي) 2\n\n2- اطلبي واشفعي فينا يا عذراء\nعند الهك رب القدرة\nدي شفاعتك تدينا النصرة\n(طوباكي يا مريم طوباكي)2 \n\nق) ما احلاكي يا مريم ما احلاكي\nحملتي النور في احشاكي\nاختار جمالك وبهائك\n(طوباكي يا مريم طوباكي) 2\n\n3- كنز النعمة أمي يا عذراء\nامدح فيكي ستي يا طاهرة\nدي مدايحك تعزية ونصرة\n(طوباكي يا مريم طوباكي)2 \n\nق) ما احلاكي يا مريم ما احلاكي\nحملتي النور في احشاكي\nاختار جمالك وبهائك\n(طوباكي يا مريم طوباكي) 2\n\n4- صرتي أماً لفاديكي\nمقدرش اوصف معانيكي\nده هو ابنك وفاديكي\n(طوباكي يا مريم طوباكي)2 \n\nق) ما احلاكي يا مريم ما احلاكي\nحملتي النور في احشاكي\nاختار جمالك وبهائك\n(طوباكي يا مريم طوباكي) 2"}, {"id": "pp133", "cat": "pp", "title": "ما احلاها الوقفة", "text": "1- ما احلاها الوقفة قدامك يا يسوع إلهنا في الصلوات نمجد الله نفرح نتبارك نتعزى بحديثنا يا رب معاك نمجد الله\n\nما احلاها الوقفة قدامك نطلب الرحمة والغفران نمجد الله. نشكي همومنا واتعابنا تدينا يا رب التعزيات نمجد الله.\n\nق) يا فرحنا بفادينا\nده محقق امانينا\nومسيج حوالينا\nكل فرحنا بيه\n\n2- ما احلاها الجلسة الروحية وياك يا إلهنا قدام الإنجيل نمجد الله. نفرح نتبارك نتعزى بكلامك يا عمانوئيل نمجد الله.\n\nما احلى كلامك يا إلهنا يدي سلام وفرح عظيم نمجد الله. يملأ الاواني بالبركات ويغير قلبي بقلب جديد نمجد الله. \n\nق) يا فرحنا بفادينا\nده محقق امانينا\nومسيج حوالينا\nكل فرحنا بيه\n\n3- م احلاها التوبة النقية من قلب نادم ومعاه دموع نمجد الله. في جلسة توبة وإعتراف مع الكاهن في حضور يسوع نمجد الله.\n\nما احلاها التوبة النقية لقلب مليان من الشرور نمجد الله. حالاً يشبع ويتغسل بجسد ودم الرب يسوع نمجد الله.\n\nق) يا فرحنا بفادينا\nده محقق امانينا\nومسيج حوالينا\nكل فرحنا بيه\n\n4- ما احلى حضور القداسات بخولاجي واجبية وإنجيل نمجد الله. نفرح نتبارك نتعزى بحضورنا مع السمائيين نمجد الله.\n\nما احلاها الوقفة قدامك يا إلهنا نطلب صارخين نمجد الله. تسمع وتحل المشاكل وترفع عنا كل انين نمجد الله.\n\nق) يا فرحنا بفادينا\nده محقق امانينا\nومسيج حوالينا\nكل فرحنا بيه\n\n5- ما احلى كنيستنا القبطية أم الشهداء والمعترفين نمجد الله. سر التناول بيثبت ايمانا بالرب المسيح نمجد الله. \n\nما احلاها القوة الإلهية في جسد ودم المسيح نمجد الله. قوة عظيمة تقدسنا وسلاح قوي يغلب إبليس نمجد الله.\n\nق) يا فرحنا بفادينا\nده محقق امانينا\nومسيج حوالينا\nكل فرحنا بيه\n\n6- ما احلاها العِشرة في الدنيا وانت مؤمن بالرب يسوع نمجد الله. تعيش شبعان ومتهني بفرح وسلام يفوق العقول نمجد الله. \n\nتبقى لإلهك صورة حية تشهد للكل بالسلوك نمجد الله. وثمار الروح تملأ قلبك تشهد وتحكي عن يسوع نمجد الله.\n\nق) يا فرحنا بفادينا\nده محقق امانينا\nومسيج حوالينا\nكل فرحنا بيه"}, {"id": "pp134", "cat": "pp", "title": "ماتشغلش بالك", "text": "1- وقت الازمات والضيق والكرب\nاو لما تزيد اهوال الحرب\nاطلب ربنا واصرخ من القلب\nاندهله وقوله ارحمني يا رب\nارحمني يا اللي خلقت الكون\nكيرياليسون\n\nق) ماتشغلش بالك\nخايف ليه وتخاف من ايه\nربنا موجود\n\nسلم احوالك\nكلها ليه واطلب ربنا\nتلاقيه موجود\n\nإلجأ في المحنة لرب الكون \nدايماً قوله\n كيرياليسون\n\n2- لو شُفت الاخ بيقتل اخوه\nوالابن بيقسى على امه وابوه\nولقيت الناس ناسيين الله \nمشغولة بمال زايل جمعاه\nانده ربك حملك هيهون\nكيرياليسون\n\nق) ماتشغلش بالك\nخايف ليه وتخاف من ايه\nربنا موجود\n\nسلم احوالك\nكلها ليه واطلب ربنا\nتلاقيه موجود\n\nإلجأ في المحنة لرب الكون \nدايماً قوله\n كيرياليسون"}, {"id": "pp135", "cat": "pp", "title": "ماتفكرش كتير", "text": "1- ماتفكرش كتير ده يسوع \nمش محتاج تفكير\nمتقلبش كتير بدموع\nمتقلبش كتير\n\nق) ده عارف خباياك\nده كاشف نواياك\nده قايل في وعوده\nاني هكون وياك\nماتفكرش كتير ده يسوع\nمش محتاج تفكير\n\n2- ماتفكرش كتير في حالتك ديه\nسيبها في ايد الرب\nمهما تعمل زي ماهيه\nصلي له يقرب\n\nق) ده عارف خباياك\nده كاشف نواياك\nده قايل في وعوده\nاني هكون وياك\nماتفكرش كتير ده يسوع\nمش محتاج تفكير\n\n3- لو هتشوف الدنيا انقلبت\nفكر انه معاك\nبيقول ان الدنيا اتغلبت\nساعة صلبه هناك\n\nق) ده عارف خباياك\nده كاشف نواياك\nده قايل في وعوده\nاني هكون وياك\nماتفكرش كتير ده يسوع\nمش محتاج تفكير\n\n4- ارفع كل همومك عنك\nوافرح باللي فداك\nشايل همك فرح قلبك\nرنم ويا صلاة\n\nق) ده عارف خباياك\nده كاشف نواياك\nده قايل في وعوده\nاني هكون وياك\nماتفكرش كتير ده يسوع\nمش محتاج تفكير\n\n5- شوف الفرحة وسط اخواتك\nشُفت إبليس على الباب\nشوف الرب في وسط صلاتك\nفرحان بالأحباب\n\nق) ده عارف خباياك\nده كاشف نواياك\nده قايل في وعوده\nاني هكون وياك\nماتفكرش كتير ده يسوع\nمش محتاج تفكير"}, {"id": "pp136", "cat": "pp", "title": "مجد مريم", "text": "ق) مجد مريم يتعظم\nفي المشارق والغروب\nكرموها عظموها\nملكوها في القلوب\n\n1- قد تلألأت وتعالت\nما لنورها غروب\nوهي قالت حين نالت\nفلتطوبني الشعوب\n\nق) مجد مريم يتعظم\nفي المشارق والغروب\nكرموها عظموها\nملكوها في القلوب\n\n2- قد رآها واصطفاها\nرب كل العالمين\nووقاها مذ براها\nكل محظور يشين\n\nق) مجد مريم يتعظم\nفي المشارق والغروب\nكرموها عظموها\nملكوها في القلوب\n\n3- هي رجاكم في شقاكم\nفاسمعوا يا خاطئين\nلا تخافوا أن توافوا\nلحماها طالبين\n\nق) مجد مريم يتعظم\nفي المشارق والغروب\nكرموها عظموها\nملكوها في القلوب\n\n4- هي تُعرف هي تُوصَف\nإنها ملجأ أمين\nفاقصدوها تجدوها\nلمعونتكم تميل\n\nق) مجد مريم يتعظم\nفي المشارق والغروب\nكرموها عظموها\nملكوها في القلوب\n\n5- اذكرينا واظرينا\nنظرة الأم للبنين\nواقبلينا واجعلينا\nبين صفوف العابدين\n\nق) مجد مريم يتعظم\nفي المشارق والغروب\nكرموها عظموها\nملكوها في القلوب\n\n6- انجدينا وارشدينا\nنحو صدق الاعتقاد\nوامنحينا تربحينا\nلأبنك حُسن الوداد\n\nق) مجد مريم يتعظم\nفي المشارق والغروب\nكرموها عظموها\nملكوها في القلوب\n\n7- لا تَمِّلي أن تصلي\nفي ربوع الخاطئين\nعلميهم وارشديهم\nإنك الملجأ الأمين \n\nق) مجد مريم يتعظم\nفي المشارق والغروب\nكرموها عظموها\nملكوها في القلوب\n\n8- ثم نسأل أن نؤهل\nلسعادة الختان\nحيث نسمع أن نكرم\nمدحك على الدوام\n\nق) مجد مريم يتعظم\nفي المشارق والغروب\nكرموها عظموها\nملكوها في القلوب"}, {"id": "pp137", "cat": "pp", "title": "محبة عجيبة", "text": "1- محبة عجيبة تدهش عقلي\nازاي ربي تموت مُهان\nازاي تحمل عاري واثمي\nوانت الإله الديان\n\nق) ده حُب عجيب\nده حُب فريد\nحُبك ظهر\nعلى الصليب\n\n2- يوم ما حيت الأرض إلينا\nصارت بشرى بالسلام\nونورك أشرق علينا\nوبدد كل الظلام\n\nق) ده حُب عجيب\nده حُب فريد\nحُبك ظهر\nعلى الصليب\n\n3- ازاي ربي تخلي بنفسك\nوتاخد صورة إنسان\nوانت إله عظيم في مجدك\nومالك كل الاكوان\n\nق) ده حُب عجيب\nده حُب فريد\nحُبك ظهر\nعلى الصليب\n\n4- مديون انا يا رب بحُبك\nاشهد عنه في كل مكان\nوأعلن كمان اني بحبك\nبالعمل مش باللسان\n\nق) ده حُب عجيب\nده حُب فريد\nحُبك ظهر\nعلى الصليب"}, {"id": "pp138", "cat": "pp", "title": "مرة تمشيني", "text": "1- مرة تمشيني على المية\nوعنيا عليك\nوإن عليت الموجة عليَّ\nتمسكني بإيدك 2\n\nق) كل مرة بشوف ايديك\nقوية وقديرة\nسلطانك ملهوش حدود\nوحلولك كتيرة 2\n\n2- مرة تشق قصادي البحر\nوعلى ارضه تمشيني\nوفرعون ومركباته\nيغرق وتعديني 2\n\nق) كل مرة بشوف ايديك\nقوية وقديرة\nسلطانك ملهوش حدود\nوحلولك كتيرة 2\n\n3- مرة تمشيني في النار\nوألاقيك عن يميني\nونبوخذنصر يحتار\nازاي بتنجيني ! 2\n\nق) كل مرة بشوف ايديك\nقوية وقديرة\nسلطانك ملهوش حدود\nوحلولك كتيرة 2\n\n4- مرة قُلت إنك نايم\nفي سفينة الحياة\nرد البحر وريحه العاصف\nده هو الإله 2\n\nق) كل مرة بشوف ايديك\nقوية وقديرة\nسلطانك ملهوش حدود\nوحلولك كتيرة 2\n\n5- مرة تسد بدهنة زيت\nديون السنين\nماليت كل فراغ في البيت\nوفي خيرك عايشين 2\n\nق) كل مرة بشوف ايديك\nقوية وقديرة\nسلطانك ملهوش حدود\nوحلولك كتيرة 2\n\n6- مرة ابليس يشهد إنك\nمسيج حوالينا\nحوالين كل ما املك\nوكل ما ليَّ 2\n\nق) كل مرة بشوف ايديك\nقوية وقديرة\nسلطانك ملهوش حدود\nوحلولك كتيرة 2"}, {"id": "pp139", "cat": "pp", "title": "مرة تهت", "text": "1- مرة تهت بعيداً \nعن مخلصي يسوع\nفأتاني من فداني\nودعاني للرجوع\n\nق) صوته الحلو ناداني\nلا تُطيلن الضلال\nاسرعنَّ يا بُنيَّ\nوتعال لي تعال\n\n2- ارجلي ادمت بشوك\nلم ارى له نظير\nبينما الصوت ينادي\nقد ضللت في المسير\n\nق) صوته الحلو ناداني\nلا تُطيلن الضلال\nاسرعنَّ يا بُنيَّ\nوتعال لي تعال\n\n3- إلا أني لم ابالي\nابداً بذا الكلام\nبل غدوت في ضلالي\nمُستهيناً بالآلام\n\nق) صوته الحلو ناداني\nلا تُطيلن الضلال\nاسرعنَّ يا بُنيَّ\nوتعال لي تعال\n\n4- صار مسلكي خطيراً\nوظلامه مخيف\nفصرخت من شقائي\nأين وجهك اللطيف\n\nق) صوته الحلو ناداني\nلا تُطيلن الضلال\nاسرعنَّ يا بُنيَّ\nوتعال لي تعال\n\n5- بعد ذا تناهى حزني\nمِن جرى ذاك الضلال\nبمرارة ناديت\nيا مخلصي تعال\n\nق) صوته الحلو ناداني\nلا تُطيلن الضلال\nاسرعنَّ يا بُنيَّ\nوتعال لي تعال\n\n6- بغتة رأيت نوراً\nفي طريقي قد بهر\nعندما الفادي المحب\nبتبسم ظهر\n\nق) صوته الحلو ناداني\nلا تُطيلن الضلال\nاسرعنَّ يا بُنيَّ\nوتعال لي تعال"}, {"id": "pp140", "cat": "pp", "title": "مريم اسم جميل", "text": "ق) مريم اسم جميل\nيشفي كل عليل\nام الله وكنز الرحمة\nوأصل التهليل\n\n1- يوم ما سمعت انك ظهرتي\nفي كنيسة الزيتون\nقلبي اشتاق علشان يشوفك يا أم الحنون\n\nطول عمري من وانا صغير\nفي حبك مفتون\nافكر فيكي يا مريم\nوألهج في السر المكنون\n\nق) مريم اسم جميل\nيشفي كل عليل\nام الله وكنز الرحمة\nوأصل التهليل\n\n2- كل ما اكب احبك اكتر\nيا حصن النجاة\nانتي الطاهرة وانتي العرش\nللرب الإله\n\nكل جروحي تروح يا مريم\nبفضل صلواتك\nوكل خير هاتشوفه عينيَّ\nبفضل شفاعتك\n\nق) مريم اسم جميل\nيشفي كل عليل\nام الله وكنز الرحمة\nوأصل التهليل\n\n3- مين غيرك يا مريم يقدر\nيرد الضالين\nمين غيرك يا مريم يشفع\nفي جموع التائبين\n\nمين غيرك يا مريم\nفي إيمان المؤمنين\nمين غيرك انتي يا مريم\nفخر المسيحيين\n\nق) مريم اسم جميل\nيشفي كل عليل\nام الله وكنز الرحمة\nوأصل التهليل\n\n4- مين احن منك انتي\nنلتجأ إليه ؟\nمين شفاعته قوية زيك\nنتكل عليه ؟\n\nمين يعرف أصلك يا مريم\nويقولي عليه ؟\nسماء انتي ولا شمس\nولا نسميكي إيه ؟\n\nق) مريم اسم جميل\nيشفي كل عليل\nام الله وكنز الرحمة\nوأصل التهليل\n\n5- كل اللي بينكر فضلك\nيجي الحزن عليه\nعرفيه يا مريم مجدك\nنوري له عينيه\n\nفي الحال يعرف مجد اسمك\nوفضايله عليه\nيبكي يقول غباوتي \nكنت بنكر ليه\n\nق) مريم اسم جميل\nيشفي كل عليل\nام الله وكنز الرحمة\nوأصل التهليل\n\n6- اشفعي فينا يا مريم\nده احنا شعب ايسوس\nتعالي وصلي في وسطينا\nوامسحي الدموع\n\nواسعدي البابا تواضروس\nخلي اسمه مرفوع\nنجحيه في كل خطوة\nوفي كل مشروع\n\nق) مريم اسم جميل\nيشفي كل عليل\nام الله وكنز الرحمة\nوأصل التهليل"}, {"id": "pp141", "cat": "pp", "title": "مسيحي حلو ويتحب", "text": "1- من غير ما تتعب وتدور\nتعالى خُد قلب منور\nمفيش غيره هو النور\nيملى القلب فرح وسرور\n\nق) مسيحي حلو ويتحب\nمكانه جوة العين والقلب\nتمشيله خطوة يمشي اتنين\nويحفظك في نن العين\n\n2- مشيلي من السماء للارض\nبُحب مالوش طول ولا عرض\nوأخلى نفسه ملك المجد\nورشي ياخد صورة عبد\n\nق) مسيحي حلو ويتحب\nمكانه جوة العين والقلب\nتمشيله خطوة يمشي اتنين\nويحفظك في نن العين\n\n3- وانت رايح قول للجاي\nمسيحي يغفر كل شئ\nزكا والخاطية وكل آثيم\nنالوا الحياة دخلوا النعيم\n\nق) مسيحي حلو ويتحب\nمكانه جوة العين والقلب\nتمشيله خطوة يمشي اتنين\nويحفظك في نن العين\n\n4- يا هناه اللي يعيش وياه\nويتبع آثار خطاه\nعمره ما يضل ولا يتعب\nولا تزل قدماه\n\nق) مسيحي حلو ويتحب\nمكانه جوة العين والقلب\nتمشيله خطوة يمشي اتنين\nويحفظك في نن العين"}, {"id": "pp142", "cat": "pp", "title": "مسيحي خلي", "text": "1- مسيحي خلي\n وزي ضلي\nمش بيفارقني\nمعايا تملي\n\nشايلني وشايل\n شيلتي كمان\nوتدبر امري\n في كل الزمان\n\n2- هو إلهي\nوهو ربي\nمسيحي في قلبي\nليه كل حبي\n\nاحلى ترنيمة\nعلى لساني\nروحه المعزي\nمالي كياني\n\n3- مسيحي معايا\nهو حمايا\nماشي قدامي\nماشي ورايا\n\nوعن يميني\nوعن يساري\nيحارب عني\nسر انتصاري\n\n4- مسيحي معايا\nوكمان جوايا\nده محوط بيَّ\nومصدر عزائي\n\nاعظم عطية\nكنز العطايا\nيا فرحة قلبي\nالله جوايا"}, {"id": "pp143", "cat": "pp", "title": "مش ممكن يرتاح قلبك", "text": "1- مش ممكن يرتاح قلبك\nوانت بعيد عن ربك\nلو ربحت العالم كله\nمش هايريح قلبك\n\nكل العالم باطل\nكله قبض الريح\nياللي عايز يرتاح قلبك\nتعالى للمسيح\n\n2- مهما تعمر في الدنيا\nبكرة لابد تموت\nاوعى الفرصة تضيع منك\nاوعى الفرصة تفوت\n\nاسمع صوت إلهك\nتعالى للمسيح\nقوله ارحمني انا الخاطي\nوانت تستريح\n\n3- وانت مسافر ع الابدية\nلابد تكون وياك\nتذكرة السفر مختومة\nبدم يسوع مولاك\n\nخُدها منه الآن\nليفوت الآوان\nترجع تندم وتضيع منك\nفرصة الغفران\n\n4- وانت ياللي في كورة بعيدة\nبعد ما كنت امير\nترجع تشتهي الخرنوب\nاللي بتاكله الخنازير\n\nكل العالم فاني\nكله أنين ودموع\nمش ممكن يشبع قلبك\nغير الرب يسوع"}, {"id": "pp144", "cat": "pp", "title": "مش هصدق", "text": "1- مش هاصدق اي صوت\nغير صوت الرب راعيَّ صوته يزلزل قلب الموت \nويصحي ايماني فيَّ\n\nق) هو ده إلهي القدير\nاللي وعد قدامي يسير\n\n2- إله مافيش عنده مُحال\nويغير مجرى الأحوال\nيأمر واللي بيأمر بيه\nلازم يتحقق في الحال\n\nق) هو ده إلهي القدير\nاللي وعد قدامي يسير\n\n3- رب بيأمر الرياح\nويهدي كل الأمواج\nيحول حزني لأفراح\nويسدد كل احتياج\n\nق) هو ده إلهي القدير\nاللي وعد قدامي يسير"}, {"id": "pp145", "cat": "pp", "title": "مشتاق للعطية", "text": "1- مشتاق للعطية. والقلب الجديد. ومؤازرة قوية. وابدأ من جديد. في حياة الخدمة القوية. والتبشير بخلاص ماسيا. قرب يجي يسوع\n\n2- مشتاق للقداسة. وصلاة الدموع. وبدون القداسة. لن أرى يسوع. حطم اصنام الخطية. حرر من العبودية. لن اعيش مهزوم\n\n3- عايز قوة جديدة. لأختار الطريق. ومناعة اكيدة. ضد عماليق. ويكون لي. ضمان النصرة. وامشي في. موكب النصرة. نصرتي يسوع\n\n4- واسكن فيَّ بروحك. قدامي في المسير. علشان دم جروحك. استخدمني سفير. وأكرز ليسوع مخلص. ومفيش غير الدم يخلص. عمل النعمة كبير "}, {"id": "pp146", "cat": "pp", "title": "معي في الطريق", "text": "1- معي في الطريق\nيا أعز صديق \nوفي وسط الضيق\nبتنجدني\n\nلمَّا بناديك\nحالاً بلاقيك\nماددلي ايديك\nوبتسندني\n\nق) وتقولي ها انا معك\nبيميني ماسكك وبرفعك\nوانا راعي ليك. دايماً براعيك\nوعيني عليك. كل الايام يا ابني\n\n2- وقت الآلام \nبتجيني قوام\nتديني سلام\nوتشجعني\n\nاناديك ربي\nالاقيك جنبي\nتطمن قلبي\nوترفعني\n\nق) وتقولي ها انا معك\nبيميني ماسكك وبرفعك\nوانا راعي ليك. دايماً براعيك\nوعيني عليك. كل الايام يا ابني\n\n3- ادعوك يا حبيب\nويا اغلى نصيب\nكُن لي مُجيب\nوقت صلاتي\n\nارجوك تسمعني\nفي ضعفي ارفعني\nإلهي شجعني\nوسط ضيقاتي\n\nق) وتقولي ها انا معك\nبيميني ماسكك وبرفعك\nوانا راعي ليك. دايماً براعيك\nوعيني عليك. كل الايام يا ابني\n\n4- بيك انا غالب\nكل التجارب\nمع المصاعب\nوالعدو مغلوب\n\nكل الايام\nوعلى الدوام\nها احتمي في الدم\nايا مصلوب\n\nق) وتقولي ها انا معك\nبيميني ماسكك وبرفعك\nوانا راعي ليك. دايماً براعيك\nوعيني عليك. كل الايام يا ابني"}, {"id": "pp147", "cat": "pp", "title": "من الأعماق يا ربي", "text": "ق) من الاعماق يا ربي\nصرخت من قلبي\nحتى تنظر إليَّ وتستجيب ليَّ\nأنا مسكين\n\n1- إذا ما صرخت إليك\nلتستقم لديك\nصلاتي كبخور تصعد بلا فتور\nايا مُجيب\n\nق) من الاعماق يا ربي\nصرخت من قلبي\nحتى تنظر إليَّ وتستجيب ليَّ\nأنا مسكين\n\n2- ليكُن رفع يداي قدامك\nكذبيحة مسائية امامك\nتغفر لي بيها ذنبي\nتطهر بيها قلبي. أيا معين\n\nق) من الاعماق يا ربي\nصرخت من قلبي\nحتى تنظر إليَّ وتستجيب ليَّ\nأنا مسكين"}, {"id": "pp148", "cat": "pp", "title": "من كل الأمم", "text": "ق) من كل الامم\nمن كل القبائل\nمن كل الشعوب\nامام العرش وقوف\n\nربوات الوف الوف\nجايين \nمن كل مكان\n\n1- جايين من ضيق وانين\nجايين من ظلم سنين\nلابسين متسربلين\nوعلى القيثارات عازفين\n\nدول المفديين\nبالدم الثمين\nشفتهم هاتفين\nوهما جايين\n\nق) من كل الامم\nمن كل القبائل\nمن كل الشعوب\nامام العرش وقوف\n\nربوات الوف الوف\nجايين \nمن كل مكان\n\n2- امام الطغاة واقفين\nيتحاكموا وهم صامتين\nعلى الظلم صابرين\nودول للسما ناظرين\n\nدول المفديين\nبالدم الثمين\nشفتهم شاكرين\nوهما جايين\n\nق) من كل الامم\nمن كل القبائل\nمن كل الشعوب\nامام العرش وقوف\n\nربوات الوف الوف\nجايين \nمن كل مكان\n\n3- وسط الاتون ماشيين\nجوة السجون راضيين\nبالروح متعزيين\nوبالمسيح مسبيين\n\nدول المفديين\nبالدم الثمين\nشفتهم فرحين\nوهما جايين\n\nق) من كل الامم\nمن كل القبائل\nمن كل الشعوب\nامام العرش وقوف\n\nربوات الوف الوف\nجايين \nمن كل مكان\n\n4- بهوان وآلام عايشين\nوصعاب وعذاب شايفين\nبأمان وسلام شاعرين\nوصوت التهليل رافعين\n\nدول المفديين\nبالدم الثمين\nشفتهم غالبين\nوهما جايين\n\nق) من كل الامم\nمن كل القبائل\nمن كل الشعوب\nامام العرش وقوف\n\nربوات الوف الوف\nجايين \nمن كل مكان\n\n5- ترس الإيمان ماسكين\nخوذة الخلاص حاملين\nقوة العدو غالبين\nوامجاد السما وارثين\n\nدول المفديين\nبالدم الثمين\nشفتهم واثقين\nوهما جايين\n\nق) من كل الامم\nمن كل القبائل\nمن كل الشعوب\nامام العرش وقوف\n\nربوات الوف الوف\nجايين \nمن كل مكان\n\n6- بيض الثياب لابسين\nولبيت الآب رايحين\nده ملايكة وقديسين\nبصوت الترحيب قابلين\n\nدول المفديين\nبالدم الثمين\nشفتهم كاملين\nوهما جايين\n\nق) من كل الامم\nمن كل القبائل\nمن كل الشعوب\nامام العرش وقوف\n\nربوات الوف الوف\nجايين \nمن كل مكان"}, {"id": "pp149", "cat": "pp", "title": "مهما طال الزمان", "text": "1- مهما طال الزمان\nفي حرب وكرب وهوان\nيسوع اعد السماء لينا\nوفي انتظارنا على المينا\n\nق) ويوم ما هاتيجي وتاخدني\nمنظر جماله يسعدني\nواهتف وارنم واغني\nوفرحي لا ينزع مني\n\n2- ومهما سالت الدموع\nومهما عطش وجوع\nالأذرع الابدية\nحملتني طول البرية\n\nق) ويوم ما هاتيجي وتاخدني\nمنظر جماله يسعدني\nواهتف وارنم واغني\nوفرحي لا ينزع مني\n\n3- قلبي وروحي في انتظار\nحتى اراه على السحاب\nلما اراه هكون مثله\nلأنني ملك لشخصه\n\nق) ويوم ما هاتيجي وتاخدني\nمنظر جماله يسعدني\nواهتف وارنم واغني\nوفرحي لا ينزع مني\n\n4- وفي الختام جاي الحبيب\nواطرحوا حمل الصليب\nمجد السماء تنظره عيني\nمنظر حبيبي يعزيني\n\nق) ويوم ما هاتيجي وتاخدني\nمنظر جماله يسعدني\nواهتف وارنم واغني\nوفرحي لا ينزع مني"}, {"id": "pp150", "cat": "pp", "title": "مهما كان", "text": "ق) مهما كان مهما كان\nلينا ارض ولينا مكان\nمهما كان مهما كان\nوعده لينا ده اغلى ضمان\n\n1- مهما حارب فينا الخوف\nمهما عاندت فينا ظروف\nهو راعينا هو حامينا\nوكان في النار ويا الفتيان\n\nق) مهما كان مهما كان\nلينا ارض ولينا مكان\nمهما كان مهما كان\nوعده لينا ده اغلى ضمان\n\n2- دي العيون بتداري دموع\nلينا ارض وفيها يسوع\nلينا وطن ولينا مكان\nولينا علم بيرف كمان\n\nق) مهما كان مهما كان\nلينا ارض ولينا مكان\nمهما كان مهما كان\nوعده لينا ده اغلى ضمان\n\n3- مهما كان في الارض آلام\nدي السحابة آهي جاية قوام\nجاي تاخدنا زي ما وعدنا \nوهناك راح ننسى الاتعاب\n\nق) مهما كان مهما كان\nلينا ارض ولينا مكان\nمهما كان مهما كان\nوعده لينا ده اغلى ضمان\n\n4- مهما حاربنا الشيطان\nمهما علّا في صوته كمان\nلينا الغلبة ولو في الغربة\nاصل يسوعنا ده غلبه زمان\n\nق) مهما كان مهما كان\nلينا ارض ولينا مكان\nمهما كان مهما كان\nوعده لينا ده اغلى ضمان\n\n5- مهما كان الوقت صعيب\nبكرة شمس الغربة تغيب\nبيصبرنا ويحيي أملنا\nان يسوعنا معانا كمان\n\nق) مهما كان مهما كان\nلينا ارض ولينا مكان\nمهما كان مهما كان\nوعده لينا ده اغلى ضمان"}, {"id": "pp151", "cat": "pp", "title": "ميخائيل يا ميخائيل", "text": "ق) ميخائيل يا ميخائيل\n\nاشفع فينا يا ملاك ميخائيل\n\n1- ابدأ بأسم الله ربي\nمن فكري وصميم قلبي\nوأجيب القول ده من عندي\nفي ملاك الله ميخائيل\n\nبالقدرة الإلهية\nوالملائكة النورانية\nوأجيب القول بالكلية\nفي ملاك ميخائيل\n\nق) ميخائيل يا ميخائيل\n\nاشفع فينا يا ملاك ميخائيل\n\n2- تاج الشهداء والقديسين\nميخائيل صرنه به فرحين\nده ميخائيل رئيس عظيم\nاشفع فينا يا ملاك الله\n\nظهرت عجايب يا حُضَّار\nمع القديسين والابرار\nخلصهم من اتون النار\nاشفع فينا يا ملاك الله\n\nق) ميخائيل يا ميخائيل\n\nاشفع فينا يا ملاك ميخائيل\n\n3- صنع عجايب كتيرة شتى\nمع دورثيئوس وثاؤبستة\nحتى مع التاجر متى\nاشفع فينا يا ملاك الله\n\nصنع عجائب يا حُضَّار\nكبار وصغار\nعبيد وأحرار\nاشفع فينا يا ملاك الله\n\nق) ميخائيل يا ميخائيل\n\nاشفع فينا يا ملاك ميخائيل\n\n4- حاضر معنا ومش غايب\nوخلصنا من التجارب\nومن إبليس المحارب\nاشفع فينا يا ملاك الله\n\nزيادة النيل بطلباته\nوأعتدال الهواء في اوقاته\nوالزرع يبارك في غلاته\nاشفع فينا يا ملاك الله\n\nق) ميخائيل يا ميخائيل\n\nاشفع فينا يا ملاك ميخائيل\n\n5- وانا عندي طلبة\nالليلة دي تباركنا بركة روحية\nبشفاعة مريم ست البشرية\nاشفع فينا يا ملاك الله\n\nق) ميخائيل يا ميخائيل\n\nاشفع فينا يا ملاك ميخائيل"}, {"id": "pp152", "cat": "pp", "title": "مين غيرك نترجاه", "text": "1- مين غيرك نترجاه ؟\nمين الراحة معاه ؟\nغيرك يا رئيس الحياة !\nفيك واثقين ما هنغرقش\nلأننا فيك ماسكين\n\nوالغرقان يناديك يلقى نجاة\nوالتعبان يلقى دواه\nبيك حاسين بأمان\nوسبتنا الأحزان\nعشان انت ما بتسبناش\n\n2- مين غيرك نلجأ ليه ؟\nنرمي حمولنا عليه ؟\nمين بإيديه شال عنا كتير ؟\nآه ملناش غيرك\nما انت حنين ما بتقساش\n\nمابتنساش الباصين بدموع\nليك صارخين يا يسوع\nيا شايلنا في عنيك\nعلشان عينا عليك\nوقت الخوف ما خوفناش\n\n3- ليك حكمة وليك ترتيب\nانت يا رب عجيب\nمش بتسيب حقنا ولا بتغيب\nيهجم ديب بعصايتك تبعده \nعشان انت قدير\n\nهم كبير ليه تفسير او كان\nشئ من غير تفسير\nمش بس تحليه\nلكن بتخليه بقى\nللي يحبك خير"}, {"id": "pp153", "cat": "pp", "title": "نرى عجباً", "text": "1- نرى عجباً ان إلهاً صار جسداً الليلويا\n2- إله قدير ولد حقير \nوعاش فقير الليلويا\n\n3- فهو الأبدي كان أزلي \nابن العلي الليلويا\n4- وهو المسيح به نستريح\nفله التسبيح الليلويا\n\n5- وفيه الكمال بديع الجمال\nصاحب الجلال الليلويا\n6- رُفِعَ الحبيب على الصليب\nسر عجيب الليلويا\n\n7- قد صُلِبَ البار عوض الاشرار طايع مختار الليلويا\n8- قد مات وقام في اسمى مقام فيه السلام الليلويا\n\n9- جلس الامين عن اليمين\nوهو المعين الليلويا\n10- وهو الفادي الذي يأتي\nولا يبطي الليلويا\n\n11- يا ربنا انجز لنا\nانتظارنا الليلويا"}, {"id": "pp154", "cat": "pp", "title": "نور عيني", "text": "1- انا الاعمى بدون رفيق\nلا ليَّ صاحب ولا صديق\nجالس استعطي في الطريق\nنور عيني حبيبي يسوع\n\nق) نور عيني\nحبيبي يسوع\nنور عيني\nحبيبي يسوع\n\n2- بالبشرى جاني خبر مسموع\nيسوع ماشي وسط الجموع\nصرخت ارحمني يا يسوع\nنور عيني حبيبي يسوع\n\nق) نور عيني\nحبيبي يسوع\nنور عيني\nحبيبي يسوع\n\n3- احد التلاميذ انتهرني\nعلى صوت صراخي انتقدني\nيسوع اتحنن وسألني\nنور عيني حبيبي يسوع\n\nق) نور عيني\nحبيبي يسوع\nنور عيني\nحبيبي يسوع\n\n4- مايهمنيش المنتقدين\nيسوع صادق ووعده امين\nتفل على الارض وصنع طين\nنور عيني حبيبي يسوع\n\nق) نور عيني\nحبيبي يسوع\nنور عيني\nحبيبي يسوع\n\n5- شفق عليَّ انا الفقير\nقلبي م الفرح هايطير\nكنت اعمى والان بصير\nنور عيني حبيبي يسوع\n\nق) نور عيني\nحبيبي يسوع\nنور عيني\nحبيبي يسوع\n\n6- كل الوديان ها انا اخبر\nلفادي الخطاب انا ابشر\nكنت اعمى والان ابصر\nنور عيني حبيبي يسوع\n\nق) نور عيني\nحبيبي يسوع\nنور عيني\nحبيبي يسوع\n\n7- على ايه يا ناس تنتهروني\nانا كامل السن اسألوني\nيسوع جه وفتح لي عيوني\nنور عيني حبيبي يسوع\n\nق) نور عيني\nحبيبي يسوع\nنور عيني\nحبيبي يسوع\n\n8- انا جيت يا خاطي يا سعدك\nصدقني ده يسوع بيحبك\nويفتحلك عيون قلبك\nنور عيني حبيبي يسوع\n\nق) نور عيني\nحبيبي يسوع\nنور عيني\nحبيبي يسوع"}, {"id": "pp155", "cat": "pp", "title": "نورتم كنيستنا", "text": "1- بنطلب منكم شفاعات\nوقت الأزمات والضيقات\nده انتم لينا في السموات\nالملجأ امام الإله\n\nنصرخ ليكم بالدموع\n(قدموها للرب يسوع) 3\nانبا كاراس السائح\nبابا كيرلس السادس\n\nق) نورتم كنيستنا\nيا مصدر بركتنا\nانبا كاراس يا شفيعنا\nبابا كيرلس يا حبيبنا\n\n2- يا كنيستنا القبطية\nعظيمة يا ام الشهداء\nانتي لينا هنا السماء\nوسفينة النجاة\n\nفيكي العذراء ام النور\n(ومارمرقس الرسول)3\nانبا كاراس السائح\nوالبابا كيرلس السادس\n\nق) نورتم كنيستنا\nيا مصدر بركتنا\nانبا كاراس يا شفيعنا\nبابا كيرلس يا حبيبنا\n\n3- نلقى فيها القديسين\nوالشهداء والمعترفين\nوالملايكة مسبحين \nللرب الفادي الامين\n\nياللا يا شعب الإله \n(نشترك مع السماء)3\nونكرم انبا كاراس\nوحبيبنا البابا كيرلس\n\nق) نورتم كنيستنا\nيا مصدر بركتنا\nانبا كاراس يا شفيعنا\nبابا كيرلس يا حبيبنا\n\n4- دقي دقي يا اجراس\nوأعلني لكل الناس\nده يسوع وحده الخلاص\nمهما ان كان لون الناس\n\nنطلب جوة كنيسة الله\n(وعيونا إلى السماء)3\nشفاعة انبا كاراس\nوالبابا كيرلس للخطاة\n\nق) نورتم كنيستنا\nيا مصدر بركتنا\nانبا كاراس يا شفيعنا\nبابا كيرلس يا حبيبنا\n\n5- طوباك انت يا مسيحي\nهنا في الارض وفي السماء\nبدمه فداك يسوع\nواصبحت وارث امجاد\n\nاتألم علشان يفديك\n(والمجد والعز ليك)3\nونشوف البابا كيرلس\nوانبا كاراس حبيب المسيح\n\nق) نورتم كنيستنا\nيا مصدر بركتنا\nانبا كاراس يا شفيعنا\nبابا كيرلس يا حبيبنا\n\n6- يللا نسيب مجد العالم\nونمسك في ايد يسوع\nيشبعنا بمجد سماوي\nلا فيه عطش ولا جوع\n\nنعيش في السماء فرحانين\n(مع كل القديسين)3\nانبا كاراس السائح\nوالبابا كيرلس السادس\n\nق) نورتم كنيستنا\nيا مصدر بركتنا\nانبا كاراس يا شفيعنا\nبابا كيرلس يا حبيبنا\n\n7- يا انبا كاراس في 8 ابيب\nتذكار نياحتك لنا عيد\nوكمان البابا كيرلس\nنياحته 30 امشير\n\nالكل طالب شفاعات\n(قدام يسوع رب القوات)3\nوالشعب ماسك الشموع\nطالبين شفاعتكم من يسوع\n\nق) نورتم كنيستنا\nيا مصدر بركتنا\nانبا كاراس يا شفيعنا\nبابا كيرلس يا حبيبنا"}, {"id": "pp156", "cat": "pp", "title": "هقول ان انت قُلت", "text": "ق) ها اقول ان انت قُلت\nمتخافش انا معاك\nويقولوا صبرت ونُلت\nبالخير اللي في رضاك\n\n1- ها اقول على اللي عداني\nبأيديه في وسط المية\nواللي عجايبه وراني\nوالعدو مقدرش عليَّ\nها اقول ان انت قُلت\nماتخافش انا معاك\n\nق) ها اقول ان انت قُلت\nمتخافش انا معاك\nويقولوا صبرت ونُلت\nبالخير اللي في رضاك\n\n2- ها اقول في اتون النار\nكان هو مستنيني\nده الرابع بيَّ صار\nخارج مرفوعة جبيني\nها اقول ان انت قُلت \nماتخافش انا معاك\n\nق) ها اقول ان انت قُلت\nمتخافش انا معاك\nويقولوا صبرت ونُلت\nبالخير اللي في رضاك\n\n3- ها اقول حُبه عوضني\nعن اللي شُفته زمان\nفي تعبي ويأسي ما سابني\nنساني كل الأحزان\nها اقول ان انت قُلت \nماتخافش انا معاك\n\nق) ها اقول ان انت قُلت\nمتخافش انا معاك\nويقولوا صبرت ونُلت\nبالخير اللي في رضاك\n\n4- ها اقول للصديق خير\nوالرحمة كمان تبعاك\nوجهك امامك بيصير \nعلى كل امور تعباك\nها اقول ان انت قُلت \nماتخافش انا معاك\n\nق) ها اقول ان انت قُلت\nمتخافش انا معاك\nويقولوا صبرت ونُلت\nبالخير اللي في رضاك\n\n5- ها اقول على اللي وعدني\nهايمشي معايا الرحلة\nدعوته في ضيقي نجدني\nوالمُرة معاه راح تحلى\nها اقول ان انت قُلت\nماتخافش انا معاك\n\nق) ها اقول ان انت قُلت\nمتخافش انا معاك\nويقولوا صبرت ونُلت\nبالخير اللي في رضاك\n\n6- ها اقول هاتوا الرباب\nنسبحة على العظمة\nوانفتحي يا ابواب\nدا إلهي عدا الأزمة\nها اقول ان انت قُلت \nماتخافش انا معاك\n\nق) ها اقول ان انت قُلت\nمتخافش انا معاك\nويقولوا صبرت ونُلت\nبالخير اللي في رضاك"}, {"id": "pp157", "cat": "pp", "title": "وأحنا في الخطية", "text": "1- (واحنا في الخطية\nحبيتنا يا يسوع)2\n(اعطيتنا الخلاص\nوباركت الجموع)2\n\nق) احنا اولادك هنرنملك\nيا ابونا يا غالي\nإلهنا وفادينا يسوع\nليك المجد العالي\n\n2- (واحنا في الامراض\nنطلب يا يسوع)2\n(وايدك تلمسنا\nتداوي الجروح)2\n\nق) احنا اولادك هنرنملك\nيا ابونا يا غالي\nإلهنا وفادينا يسوع\nليك المجد العالي\n\n3- (واحنا في الاحزان\nنلجألك يا يسوع)2\n(تيجي بالامجاد\nتعزي النفوس)2\n\nق) احنا اولادك هنرنملك\nيا ابونا يا غالي\nإلهنا وفادينا يسوع\nليك المجد العالي\n\n4- (واحنا لمّا نيأس\nنطلب النجاة)2\n(وبنعمة روحك فينا\nتدينا الرجاء)2\n\nق) احنا اولادك هنرنملك\nيا ابونا يا غالي\nإلهنا وفادينا يسوع\nليك المجد العالي\n\n5- (واحنا في الضيقات\nنصلي بإيمان)2\n(دا إله النجدة\nيمنحنا السلام)2\n\nق) احنا اولادك هنرنملك\nيا ابونا يا غالي\nإلهنا وفادينا يسوع\nليك المجد العالي\n\n6- (واحنا في الحروب\nهنقاوم إبليس)2\n(وبقوتك انت\nنغلبه وندوس)2\n\nق) احنا اولادك هنرنملك\nيا ابونا يا غالي\nإلهنا وفادينا يسوع\nليك المجد العالي\n\n7- (واحنا في الإحتياج\nنيجيلك يا يسوع)2\n(من خيرك تشبعنا\nوتروي النفوس)2\n\nق) احنا اولادك هنرنملك\nيا ابونا يا غالي\nإلهنا وفادينا يسوع\nليك المجد العالي"}, {"id": "pp158", "cat": "pp", "title": "وحدك يا يسوع", "text": "ق) وحدك يا يسوع\nوليس سواك\nاحبك يا يسوع\nولا حدش وياك\n\n1- تهت في القفار\nعاتياً جبار\nوكان مصيري النار\nقبل ما اجي وياك\n\nق) وحدك يا يسوع\nوليس سواك\nاحبك يا يسوع\nولا حدش وياك\n\n2- القلب كان قاسي\nوفضلت انا قاسي\nولما فاض كأسي\nبديت اعيش وياك\n\nق) وحدك يا يسوع\nوليس سواك\nاحبك يا يسوع\nولا حدش وياك\n\n3- انت اللي فاديتني\nفي همومي وعزيتني\nبلمسة واحدة شفيتني\nوبنظرة سرت معاك\n\nق) وحدك يا يسوع\nوليس سواك\nاحبك يا يسوع\nولا حدش وياك\n\n4- م الكسرة للنصرة\nوزالت الحسرة\nوسعدت بالحضرة\nلما اتقابلت معاك\n\nق) وحدك يا يسوع\nوليس سواك\nاحبك يا يسوع\nولا حدش وياك\n\n5- فزت باللقاء\nوتتحقق الرجاء\nحلقت في السماء\nلما اتقابلت معاك\n\nق) وحدك يا يسوع\nوليس سواك\nاحبك يا يسوع\nولا حدش وياك\n\n6- مسحت لي دموعي\nضمدت لي جروحي\nحياتي وروحي\nسابحة في أعلى سماك\n\nق) وحدك يا يسوع\nوليس سواك\nاحبك يا يسوع\nولا حدش وياك\n\n7- رسمك ده في خيالي\nدايماً على بالي\nوالعيشة تهنالي\nلما اختلي وياك\n\nق) وحدك يا يسوع\nوليس سواك\nاحبك يا يسوع\nولا حدش وياك\n\n8- في العمق هيام\nوفي العلا احلام\nفي الصحو والمنام\nاسعد انا برؤياك\n\nق) وحدك يا يسوع\nوليس سواك\nاحبك يا يسوع\nولا حدش وياك\n\n9- دي نعمة غنية\nاعددتها ليَّ\nاعطيتها لي هدية\nلما مشيت وياك\n\nق) وحدك يا يسوع\nوليس سواك\nاحبك يا يسوع\nولا حدش وياك"}, {"id": "pp159", "cat": "pp", "title": "وسط البحر الهايج", "text": "1- وسط البحر الهايج وانا ساير\nتضربني امواجه تجعلني حاير\nويسوع باين تركني\nولا عدت اشوفه من ضعف ايماني\n\nق) يسوع لمَّا رآني اسرع إليَّ\nفي يأسي وظلامي نور عينيَّ\nلمَّا شُفته صرخت ارحمني\nجه انقذني واتحنن عليَّ\n\n2- صوت الرياح مخيف يزعج آذاني\nهول الليل وظلامه هدد سلامي\nوالدموع لا تترك عيني\nوالنعاس الهادي قد فارق اجفاني\n\nق) يسوع لمَّا رآني اسرع إليَّ\nفي يأسي وظلامي نور عينيَّ\nلمَّا شُفته صرخت ارحمني\nجه انقذني واتحنن عليَّ\n\n3- اخذت المجداف اجدف خابت آمالي\nضعفي وعجزي وجهلي زود احزاني\nويسوع ع الشط شايفني\nامتى تيجي يا ربي وتردلي آمالي\n\nق) يسوع لمَّا رآني اسرع إليَّ\nفي يأسي وظلامي نور عينيَّ\nلمَّا شُفته صرخت ارحمني\nجه انقذني واتحنن عليَّ\n\n4- كنت غرقان ويآس وأملي مقطوع\nجيت ليسوع حبيبي أذرفله الدموع\nلمَّا رآني عطف عليَّ\nمد ايده الحلوة ومسحلي عينيَّ\n\nق) يسوع لمَّا رآني اسرع إليَّ\nفي يأسي وظلامي نور عينيَّ\nلمَّا شُفته صرخت ارحمني\nجه انقذني واتحنن عليَّ"}, {"id": "pp160", "cat": "pp", "title": "يا اللي بترفع عبدك", "text": "1- يا اللي بترفع عبدك بأيديك\nالمليانة إحسان\nيا اللي بتتقدم خطواته\nتحميه من الشيطان\nانا جايلك وانا بطرح نفسي\nيا سنيد اتعبان\n\nق) يا حبيب قلبي\nبكل القلب بجيلك\nيا غني في النعمة\nده مفيش تاني مثيلك\n\n2- أنت الأعظم انت الاكبر\nمهما تكون احداث\nكلمتك انت الباقية الثابتة\nقدام قول الناس\nواللي هيحصل بكرة وبعده\nمشيئتك فوق الراس\n\nق) يا حبيب قلبي\nبكل القلب بجيلك\nيا غني في النعمة\nده مفيش تاني مثيلك\n\n3- اللي في ضلك واللي في سترك\nده ما يتخافش عليه\nبير او حتى اتون واسود\nبنفسك ها تعديه\nوها تصنع في حياته عجائب\nوايدك بتعليه\n\nق) يا حبيب قلبي\nبكل القلب بجيلك\nيا غني في النعمة\nده مفيش تاني مثيلك"}, {"id": "pp161", "cat": "pp", "title": "يا اللي حولت المرارة", "text": "1- يا اللي حولت المرارة\nاللي في حياتي لترنيمات\nحتى ضعفي وجهل قلبي \nما منعش الإحسانات\n\nكل ثانية في عمري عدت\nلو هاتحكي تقول كتير\nكل نبضة في قلبي غنت\nبفتكرلك كل خير\n\nق) بفتكرلك بفتكرلك\nبفتكرلك كل خير\n\n2- لولا مسكة ايدك انت\nكنت اضيع ويا اللي ضاع\nانا مش افضل من اللي \nخان وانكر واللي باع\n\nقلبي مديونلك يا غالي\nعمري كله اعيش اسير\nنعمتك رأفت بحالي\nراح تكمل يا قدير\n\nق) بفتكرلك بفتكرلك\nبفتكرلك كل خير\n\n3- إحساناتك تاج وطوق\nعلى راسي وعلى قلبي\nجوهر التاج اللي فوق\nده كله موت الصلب ربي\n\nده اللي خلاني آجي ساجد\nوأحني راسي واقول صغير\nبالصليب انا صرت واجد\nفي المسيح نعمة المصير\n\nق) بفتكرلك بفتكرلك\nبفتكرلك كل خير"}, {"id": "pp162", "cat": "pp", "title": "يا اللي مليت", "text": "1- ياللي مليت حياتي افراح\nبعد ما كنت بعيد\nخليت حزني ماضي وراح\nوابتدأت الاناشيد\n\nق) فرحك جوة القلب يا سيدي\nهو سروري ومصدر عيدي\nولا يتأثر باللي بيحصل\nاو ايه مهما ان كان\n\n2- ارتوى قلبي بغمر كلامك\nاللي يرد الروح\nكلمة تداوي وكلمة تعزي\nوكلمة تشيل النوح\n\nق) فرحك جوة القلب يا سيدي\nهو سروري ومصدر عيدي\nولا يتأثر باللي بيحصل\nاو ايه مهما ان كان\n\n3- املأ حياتي بثمر الخدمة\nناس تتعرف بيك\nواشارك السماء افراحها\nبخاطي واحد بيرجع ليك\n\nق) فرحك جوة القلب يا سيدي\nهو سروري ومصدر عيدي\nولا يتأثر باللي بيحصل\nاو ايه مهما ان كان\n\n4- مستنيك يوم لما تجيني\nتكتمل الافراح\nيوم عرس الخروف \nنتهلل وتنتهي الجراح\n\nق) فرحك جوة القلب يا سيدي\nهو سروري ومصدر عيدي\nولا يتأثر باللي بيحصل\nاو ايه مهما ان كان"}, {"id": "pp163", "cat": "pp", "title": "يا إلهي كتَّر خيرك", "text": "1- يإلهي كتر خيرك\nإله طيب ورؤوف\nماتحوجنيش لغيرك\nعندك م الرزق بحور\nتسامحني لما باجيلك\nوتمشيني في النور\n\nق) بغلط وبتغفر ليَّ\nوبتمسح اي ذنوب\nدائماً بتنادي عليَّ\nبسمع صوتك وبتوب\nفي حماك وياك\nشمسي ماتعرفشي غروب\n\n2- ياللي فديتني بصليبك\nوغسلتني بدماك\nمش ممكن ابداً اسيبك\nولا لحظة عين هنساك\nما انا عارف اني حبيبك\nيا حبيبي حياتي معاك\n\nق) بغلط وبتغفر ليَّ\nوبتمسح اي ذنوب\nدائماً بتنادي عليَّ\nبسمع صوتك وبتوب\nفي حماك وياك\nشمسي ماتعرفشي غروب\n\n3- دي سفينتي يا رب غريقة\nوانت نجدتي يا يسوع\nفرحني وجودك فيها\nوشفيت قلبي الموجوع\nويايا دقيقة بدقيقة\nحُبك فيَّ مزروع\n\nق) بغلط وبتغفر ليَّ\nوبتمسح اي ذنوب\nدائماً بتنادي عليَّ\nبسمع صوتك وبتوب\nفي حماك وياك\nشمسي ماتعرفشي غروب"}, {"id": "pp164", "cat": "pp", "title": "يا ام النور يا جميلة", "text": "1- انتي يا عذراء طوباوية\nفي جموع البشرية\nوانتي رمز البتولية\nنرجوكي اشفعي فينا\n\nق) يا ام النور يا جميلة\nيا عدرا يا طاهرة يا نبيلة\nيا بنت يواقيم يا اصيلة\nنرجوكي اشفعي فينا\n\n2- يا فخر كل العذارى\nانتي كلك طهارة\nوانتي مجد النصارى\nنرجوكي اشفعي فينا\n\nق) يا ام النور يا جميلة\nيا عدرا يا طاهرة يا نبيلة\nيا بنت يواقيم يا اصيلة\nنرجوكي اشفعي فينا\n\n3- يا مريم نلنا الافراح\nلما بخور عبيرك فاح\nنال الضيقة والآلام\nنرجوكي اشفعي فينا\n\nق) يا ام النور يا جميلة\nيا عدرا يا طاهرة يا نبيلة\nيا بنت يواقيم يا اصيلة\nنرجوكي اشفعي فينا\n\n4- لينا يا مريم ظهرتي\nواشكال نورانية اخذتي\nبخور وحمام وكمان سحب\nنرجوكي اشفعي فينا\n\nق) يا ام النور يا جميلة\nيا عدرا يا طاهرة يا نبيلة\nيا بنت يواقيم يا اصيلة\nنرجوكي اشفعي فينا\n\n5- انتي سما جسدانية\nوكمان منارة علوية\nيا فخر لكل المسيحية\nنرجوكي اشفعي فينا\n\nق) يا ام النور يا جميلة\nيا عدرا يا طاهرة يا نبيلة\nيا بنت يواقيم يا اصيلة\nنرجوكي اشفعي فينا\n\n6- يا جوهرة غالية ثمينة\nوشورية ذهب عظيمة\nوسيرتك يا عذراء جميلة\nنرجوكي اشفعي فينا\n\nق) يا ام النور يا جميلة\nيا عدرا يا طاهرة يا نبيلة\nيا بنت يواقيم يا اصيلة\nنرجوكي اشفعي فينا\n\n7- حبك يا مريم جوة القلب\nمش ممكن هايشغله حد\nلأنك انتي ام الرب\nرجوكي اشفعي فينا\n\nق) يا ام النور يا جميلة\nيا عدرا يا طاهرة يا نبيلة\nيا بنت يواقيم يا اصيلة\nنرجوكي اشفعي فينا\n\n8- حملتي يا عذراء رب الارباب\nيا فخر لكل البنات\nخدمتي العاقر اليصابات\nنرجوكي اشفعي فينا\n\nق) يا ام النور يا جميلة\nيا عدرا يا طاهرة يا نبيلة\nيا بنت يواقيم يا اصيلة\nنرجوكي اشفعي فينا\n\n9- يا مريم خلصينا\nوبفضل صلاتك نجينا\nقدام ابنك اذكرينا\nنرجوكي اشفعي فينا\n\nق) يا ام النور يا جميلة\nيا عدرا يا طاهرة يا نبيلة\nيا بنت يواقيم يا اصيلة\nنرجوكي اشفعي فينا\n\n10- اسمك يا مريم للأجيال\nفخر ونبع الكمال\nوبيكي تتحق الامال\nنرجوكي اشفعي فينا\n\nق) يا ام النور يا جميلة\nيا عدرا يا طاهرة يا نبيلة\nيا بنت يواقيم يا اصيلة\nنرجوكي اشفعي فينا\n\n11- شفيتي كل المرضى\nمن امراض خطيرة وصعبة\nلمَّا ظهرتي يا ام الرحمة\nنرجوكي اشفعي فينا\n\nق) يا ام النور يا جميلة\nيا عدرا يا طاهرة يا نبيلة\nيا بنت يواقيم يا اصيلة\nنرجوكي اشفعي فينا\n\n12- انتي الملجأ في السموات\nبتسمعي كل الصلوات\nوقت الأزمة وفي الضيقات\nنرجوكي اشفعي فينا\n\nق) يا ام النور يا جميلة\nيا عدرا يا طاهرة يا نبيلة\nيا بنت يواقيم يا اصيلة\nنرجوكي اشفعي فينا\n\n13- ظهرتي لينا وباركتينا\nوبصورتك اسعدينا\nيا أم إلهنا وفادينا\nنرجوكي اشفعي فينا\n\nق) يا ام النور يا جميلة\nيا عدرا يا طاهرة يا نبيلة\nيا بنت يواقيم يا اصيلة\nنرجوكي اشفعي فينا\n\n14- كل الآباء القديسين\nانتي اولهم لينا شفيع\nبصلواتك ردي الضالين\nنرجوكي اشفعي فينا\n\nق) يا ام النور يا جميلة\nيا عدرا يا طاهرة يا نبيلة\nيا بنت يواقيم يا اصيلة\nنرجوكي اشفعي فينا"}, {"id": "pp165", "cat": "pp", "title": "يا ام النور", "text": "1- يا أم النور ، يا فخر الأمة\nيا بدء السرور ، يا كنز النعمة\nيا أصل الحبور ، معدن الرحمة\nيا مريم ، يا ابنة يواقيم\n\n2- الرب المتعال ، الحي الموجود\nشرفك بكمال ، يا ابنة داود\nوأتاكِ غبريال ، بالسر العهود\nيا مريم ، يا ابنة يواقيم\n\n3- اعطاكِ التطويب ، بحلول النعمة \nبسر عجيب ، حملتي الكلمة\nأنقذ كل كئيب ، من وثاق الظلمة\nيا مريم ، يا ابنة يواقيم\n\n4- السلام لكِ ، يا عصا هرون\nالطوبى إليكِ ، يا ابنة صهيون\nيفرح بإسمك ، الصديقون\nيا مريم ، يا ابنة يواقيم\n\n5- افرحي يا مريم ، يا عروس مختارة\nيا نسل مُكَرَّمْ ، قبة ومنارة\nيا أصل مُعَظَّمْ ، ذا كل طهارة\nيا مريم ، يا ابنة يواقيم\n\n6- صرتي كالسموات ، حاملة القدوس \nأشرف من القوات ، عالية عن الطقوس\nنسألك الشفاعات ، أمام الرب القدوس\nيا مريم ، يا ابنة يواقيم\n\n7- نسألك يا عذراء ، يا تاج إسرائيل\nيا فرح الشهداء ، يا أصل التهليل\nشفاعة ونصرة ، أمام عمانوئيل\nيا مريم ، يا ابنة يواقيم"}, {"id": "pp166", "cat": "pp", "title": "يا امي من صغرك", "text": "1- يا امي من صغرك\nاختارك المسيح\nوبقيتي ليه اناء طاهر\n(وعيشتي بالتسبيح2\n\nق) يا امنا ايريني\nيا شفيعة في السماء\nصلي لأجل اولادك\n(اما الرب الإله)2\n\n2- يا امي يا عفيفة\nيا امينة يا قديسة\nعيشتي حياة بارة نقية\n(يا تماف صلي لينا)2\n\nق) يا امنا ايريني\nيا شفيعة في السماء\nصلي لأجل اولادك\n(اما الرب الإله)2\n\n3- بنسك واتضاع \nودموع وميطانيات\nبالمحبة وانكار الذات\n(خدمتي الامهات)2\n\nق) يا امنا ايريني\nيا شفيعة في السماء\nصلي لأجل اولادك\n(اما الرب الإله)2\n\n4- حبيتي ابو سيفين\nوصادقتي القديسين\nوكانت امك العذراء\n(ليكي ملجأ معين)2\n\nق) يا امنا ايريني\nيا شفيعة في السماء\nصلي لأجل اولادك\n(اما الرب الإله)2\n\n5- عيشتي حياة الكمال\nيا قدوة ومثال\nلكل بناتك في الدير\n(على مر الاجيال)2\n\nق) يا امنا ايريني\nيا شفيعة في السماء\nصلي لأجل اولادك\n(اما الرب الإله)2\n\n6- بقوة الايمان\nوثقة في الديان\nجزتي حروبك بسلام\n(دوستي على الشيطان)2\n\nق) يا امنا ايريني\nيا شفيعة في السماء\nصلي لأجل اولادك\n(اما الرب الإله)2\n\n7- اكملتي جهادك\nوسط كل اولادك\nبالشكر احتملتي آلامك\n(ونلتي امجادك)2\n\nق) يا امنا ايريني\nيا شفيعة في السماء\nصلي لأجل اولادك\n(اما الرب الإله)2\n\n8- بطريركنا الامين\nالبابا العظيم\nتواضروس الثاني\n(يديم رئاسته سنين)2\n\nق) يا امنا ايريني\nيا شفيعة في السماء\nصلي لأجل اولادك\n(اما الرب الإله)2\n\n9- اكثري الشفاعات\nلأجل الراهبات\nطالبين صلواتك ويانا\n(إلى مدى الاجيال)2\n\nق) يا امنا ايريني\nيا شفيعة في السماء\nصلي لأجل اولادك\n(اما الرب الإله)2\n\n10- حبيبك المسيح\nألبسك الاكاليل\nوبقيتي وياه في السماء\n(ومع القديسين)2\n\nق) يا امنا ايريني\nيا شفيعة في السماء\nصلي لأجل اولادك\n(اما الرب الإله)2"}, {"id": "pp167", "cat": "pp", "title": "يا بطل الأبطال", "text": "1- يا بطل الأبطال\nيا شهيد كل العصور\nاسمك يا روماني\nمكتوب بحروف من نور\n\nاطلبك تجيني\nتسندني تقويني\nسريع الندهة\nتشفع لي وتحميني\n\n2- يا أميرنا يا غالي\nيا ابو صيت عالي\nوسبع اكاليل\u000bعلى رأسك بتلالي\n\nكان حُبك كبير\nللرب القدير\nاحتملت كتير\nده مديحك يحلالي\n\n3- فارس شجاع مبرور\nراكب فرس من نور\nماخافش من الوالي\nوقُلت بقلب فخور\n\nقُلت بصوت عالي\nانا عبد اللي فداني\nربي وإلهي\nهو اللي نجاني\n\n4- مش هاسجد للأوثان\nانا مِلْكْ الديان\nلأنه محبة وحنان\nورحمة وغفران\n\nعايز اعيش في رضاه\nقلبي مشتاق لسماه\nوافرح بلقياه\nده مفيش غيره إله\n\n5- أمر داديانوس \nبعذابك يا قديس\nيا حبيب الرب ايسوس\nيا جوهر نفيس\n\nقوي في عزيمتك\nبقوة ربك\nوانت ولا همك\nكل حيل ابليس\n\n6- في الجير الحي دفنوك\nوالسم كمان سقوك\nوعلامة الصليب\nقوتك يا حبيب\n\nبالدبابيس ضربوك\nفي الهينبازين وضعوك\nصرخت لإلهك \nده يسوع منك قريب\n\n7- يسوع هو إلهي\nاللي بحبه سباني\nونجى نفسي\nمن الموت احياني\n\nيسوع هو رجائي\nيسوع هو خلاصي\nوهو حبيب قلبي\nوبصليبه فداني\n\n8- مُتّ ثلاث ميتات\nعلى اسم القدوس\nوفي كل مرة تقوم\nفيها سليم محروس\n\nناس كتير آمنت\nبقوة يسوع شهدت\nلما شافت قوة\nايمان جيؤرجيوس\n\n9- وفي رابع موتة\nانطلقت بتهليل\nوالملائكة بالأكاليل\nلمارجرجس الامير\n\nمين زيك يا بطلنا ؟\nصورتك في احلامنا\nدائماً قدامنا\nقدوة على مر العصور\n\n10- نُلت سبع اكاليل\nبالفرح والتهليل\nمن زيك يا شهيد ؟\nمحبوب عند الجميع\n\nعظيمة كرامتك\nيا امير الشهداء\nيا حبيب الملايين\nنذكرك كل حين\n\n11- طوباك يا جيؤرجيوس\nيا ابن انسطاسيوس\nيا حبيب الرب ايسوس\nإلهنا القدوس\n\nيا من بشجاعتك\nحفظت لنا الايمان\nمن يد الطغيان\nعُبَّاد الاوثان\n\n12- مارجرجس يا حبيبنا\nيا منور كنيستنا\nيا امير شهدائنا\nومفرح قلوبنا\n\nاطلب من الرب عنا\nبصلاتك يحرسنا\nويثبت ايمانا\nويشفي امراضنا\n\n13- اطلب من إلهنا\nعن البابا بطركنا\nوجميع اساقفتنا\nوسائر كهنتنا\n\nولا تنسى يا اميرنا\nاديرتنا وكنائسنا\nورهبانا وراهباتنا\nوكل اولادنا"}, {"id": "pp168", "cat": "pp", "title": "يا حُسنها مدينة", "text": "1- يا حُسنها مدينة\nنازلة من السماء\nمدينة باقية \nأعدها الرب لنا\n\n2) مدينة عظيمة\nفي زينة شبه العروس\nاوصافها مجيدة\nوفيها لذة النفوس\n\n3- مدينة منيرة\nبغير شمس او سراج\nفنور شمس او قمر\nليس فيها اي احتياج\n\n4- فالمجد قد أنارها\nمجد الإله ذي الجلال\nوشمسها ذاك الحمل\nيسطع نوراً وجمال\n\n5- وفيها نهر قد صفا\nونبعه ماء الحياة\nنظير بلوراً اضاء\nيخرج من عرش الإله\n\n6- في روضها اشهى الشجر\nاثمارها احلى الثمر\nاوراقها تشفي البشر\nبعد كل سقم او ضرر\n\n7- الدمع فيها يُمسَح\nواللعنة لا توجد\nوالقلب فيها يفرح\nبربنا المُمَجَدْ\n\n8- وفيها ينتهي الجسد\nوتبطل كل الشرور\nوفيها نبقى للأبد\nويكمل لنا السرور"}, {"id": "pp169", "cat": "pp", "title": "يا خاطي اعرف طريقك", "text": "1- يا خاطي اعرف طريقك\nوارجع لربك وتوب\nخُد المسيح من نصيبك\nاعظم نصيب للشعوب\n\nق) النور ينور حياتك\nنور المسيح العجيب\nويغسلك من ذنوبك\nيسوع بدم الصليب\n\n2- ابليس بيخدع ضميرك\nابليس بيخدع عينيك\nفي الدنيا دايماً بيغريك\nابليس بيكذب عليك\n\nق) النور ينور حياتك\nنور المسيح العجيب\nويغسلك من ذنوبك\nيسوع بدم الصليب\n\n3- اهرب من الدنيا حالاً\nواسمع لقول الكتاب\nكل اللي في الدنيا باطل\nاشواك ومر وعذاب\n\nق) النور ينور حياتك\nنور المسيح العجيب\nويغسلك من ذنوبك\nيسوع بدم الصليب\n\n4- يسوع يحقق مالك\nإن كنت تلجأ إليه\nتعالى سَلّم له قلبك\n وألق حملك عليه\n\nق) النور ينور حياتك\nنور المسيح العجيب\nويغسلك من ذنوبك\nيسوع بدم الصليب\n\n5- أهرب من الدنيا حالاً\nوآمن برب الصليب\nواطلبه من كل قلبك\nلأنه دائماً قريب\n\nق) النور ينور حياتك\nنور المسيح العجيب\nويغسلك من ذنوبك\nيسوع بدم الصليب\n\n6- في لحظة واحدة تتغير\nوتصبح ابناً سعيد\nمن الخطية تتحرر\nوتتولد من جديد\n\nق) النور ينور حياتك\nنور المسيح العجيب\nويغسلك من ذنوبك\nيسوع بدم الصليب\n\n7- وتضمن الابدية\nوتعيش في فلك النجاة\nمع الكنيسة المفدية\nفي ظل رب الحياة\n\nق) النور ينور حياتك\nنور المسيح العجيب\nويغسلك من ذنوبك\nيسوع بدم الصليب"}, {"id": "pp170", "cat": "pp", "title": "يا خاطي توب", "text": "1- يا خاطي توب تعالى لربك\nباكي ونادم افتكر ذنبك\nيرحب بيك يسوع الحبيب\nيعطيك سلام\n\n2- وليه يا خاطي عايش حيران\nوالرب إلهك نبع السلام\nتعالى إليه عند قدميه\nيغفرلك ذنبك\n\n3- افتكر دائماً دمه الثمين\nاللي نجاك من الجحيم\nخلانا ابرار وكمان احرار\nمن الخطية\n\n4- ومهما كانت خطية صعبة\nانظر لإلهك بدموع التوبة\nيسرع إليك يمسك بإيديك\nولصدره يضمك\n\n5- خلي حياتك مع يسوع\nوكُل واشرب من الينبوع\nجسده الكريم دمه الثمين\nحياة ونعيم\n\n6- تسمع إلهك يقولك يا ابني\nالسما ادخل مع كل حبايبي\nتسبيح وألحان على الدوام\nبفرح وسرور"}, {"id": "pp171", "cat": "pp", "title": "يا خاطي يا مسكين", "text": "1- يا خاطي يا مسكين\nليه بس عايش حزين\nوانت ابن المسيح\nاللي فداك ع الصليب\n\nق) قُم افرح ورتل\nومجد اسم الله\nمتخافش اطمن\nابوك ملك السما\n\n2- كم مرة يسوع دعاك\nوخبط على بابك\nوانت مقسي قلبك\nمخدوع من العالم\n\nق) قُم افرح ورتل\nومجد اسم الله\nمتخافش اطمن\nابوك ملك السما\n\n3- ضحك عليك ابليس\nنساك وصايا المسيح\nعشت حياتك جريح\nربك رؤوف رحيم\n\nق) قُم افرح ورتل\nومجد اسم الله\nمتخافش اطمن\nابوك ملك السما\n\n4- بتوبة ارجع قوام\nزي الاباء زمان\nموسى الاسود مثال\nوابن الدموع كمان\n\nق) قُم افرح ورتل\nومجد اسم الله\nمتخافش اطمن\nابوك ملك السما\n\n5- يسوع صاحب السلطان\nعلى الخطايا والآثام\nبالنعمة تصبح مليان\nوثمار الروح تنال\n\nق) قُم افرح ورتل\nومجد اسم الله\nمتخافش اطمن\nابوك ملك السما\n\n6- يللا يا خاطي خُد قرار\nوبسرعة لا تتأخر\nهاتنجوا من حر النر\nوتكون مع الابرار\n\nق) قُم افرح ورتل\nومجد اسم الله\nمتخافش اطمن\nابوك ملك السما\n\n7- مهما كانت خطاياك\nيسوع بالدم اشتراك\nوفوق الصليب فداك\nنجاك من الهلاك\n\nق) قُم افرح ورتل\nومجد اسم الله\nمتخافش اطمن\nابوك ملك السما\n\n8- وعد المسيح آمين\nلكل التائبين\nينالوا مجد عظيم\nوفرح مجيد ثمين\n\nق) قُم افرح ورتل\nومجد اسم الله\nمتخافش اطمن\nابوك ملك السما\n\n9- طوباك هنا وهناك\nياللي عشت الجهاد\nبالنسك والصلوات\nهاتورث الامجاد\n\nق) قُم افرح ورتل\nومجد اسم الله\nمتخافش اطمن\nابوك ملك السما\n\n10- فرَّح قلب يسوع\nبالتوبة والرجوع\nبعد ضلال وشرور\nإلى حضن الآب أبوك\n\nق) قُم افرح ورتل\nومجد اسم الله\nمتخافش اطمن\nابوك ملك السما\n\n11- تعالى وانسى اللي فات\nسلِّم ماضيك للآب\nيعطيك نعمة وثبات\nوسلام دائم وإيمان\n\nق) قُم افرح ورتل\nومجد اسم الله\nمتخافش اطمن\nابوك ملك السما"}, {"id": "pp172", "cat": "pp", "title": "يا خطية مليتي", "text": "1- يا خطية مليتي حياتي دموع\nزودتي احزاني\nانبا كاراس يا حبيب يسوع\nصلي علشاني\n\nق) ارجوك صليلي يا انبا كاراس\nارجوك لا تنساني\nنفسي اعيش للمخلص\nوالشهوة منعاني\n\n2- دا انا كل ما اقول اخر مرة\nارجع لها تاني\nايامي يا انبا كاراس مُرة\nوالفرحة نسياني\n\nق) ارجوك صليلي يا انبا كاراس\nارجوك لا تنساني\nنفسي اعيش للمخلص\nوالشهوة منعاني\n\n3- انا نفسي اتوب واعيش طاهر\nواعود للي فداني\nوالرب يسوع قدامي ظاهر\nوذنوبي عمياني\n\nق) ارجوك صليلي يا انبا كاراس\nارجوك لا تنساني\nنفسي اعيش للمخلص\nوالشهوة منعاني\n\n4- اجري وراء شهواتي بنفسي\nحبيت عالم فاني\nغرقان في احزاني ويأسي\nوالشهوة ملياني\n\nق) ارجوك صليلي يا انبا كاراس\nارجوك لا تنساني\nنفسي اعيش للمخلص\nوالشهوة منعاني\n\n5- ياللي معاك الاحزان بتزول\nاهدم لي اوثاني\nتوبني يا رب فأتوب\nقوي لي ايماني\n\nق) ارجوك صليلي يا انبا كاراس\nارجوك لا تنساني\nنفسي اعيش للمخلص\nوالشهوة منعاني"}, {"id": "pp173", "cat": "pp", "title": "يا رب انا ابنك", "text": "1- يا رب انا ابنك\nمحتاج لمعونة منك\nبيها اتحدى الشياطين\nوانتصر انا بأسمك\n\nق) انت يا رب عظيم\nطبيب دايماً ورحيم\nفاتح احضانك لأولادك\nمهما ان كانوا خاطئين\n\n2- يا رب انت القدير\nوعدتنا وعد أمين\nقُلت تعالوا إليَّ \nيا جميع المتعبين\n\nق) انت يا رب عظيم\nطبيب دايماً ورحيم\nفاتح احضانك لأولادك\nمهما ان كانوا خاطئين\n\n3- يا رب ابنك محتاج\nبنعمة إلهية\nتزيل همومي مع يأسي\nوأحيا بالحرية\n\nق) انت يا رب عظيم\nطبيب دايماً ورحيم\nفاتح احضانك لأولادك\nمهما ان كانوا خاطئين\n\n4- يا رب ابنك ضعيف\nوللخطية اسير\nلكن انا واثق في قدرتك\nهاتحررني يا قدير\n\nق) انت يا رب عظيم\nطبيب دايماً ورحيم\nفاتح احضانك لأولادك\nمهما ان كانوا خاطئين\n\n5- يا رب ابنك تعبان\nمن حروب الشيطان\nاوهبني توبة نقية\nلأعيش معاك فرحان\n\nق) انت يا رب عظيم\nطبيب دايماً ورحيم\nفاتح احضانك لأولادك\nمهما ان كانوا خاطئين"}, {"id": "pp174", "cat": "pp", "title": "يا رب انت عندك", "text": "1- يا رب انت عندك\nكل البركات\nواللي يطلب منك\nتدفئه بسخاء\n\nق) يا رب انت وحدك\nتغفر الآثام\nتشفي كل المرضى\nوتعول الايتام\n\n2- يا رب انت عالم\nبأحوال كل الناس\nاملانا بالنعمة\nوسدد الإحتياج\n\nق) يا رب انت وحدك\nتغفر الآثام\nتشفي كل المرضى\nوتعول الايتام\n\n3- يا رب انت المعزي\nلينا في الآلام\nترعانا وتسندنا\nوتوهبنا سلام\n\nق) يا رب انت وحدك\nتغفر الآثام\nتشفي كل المرضى\nوتعول الايتام\n\n4- يا رب انت عاطي\nجميع الخيرات\nودائماً تشبعنا\nمن خيرك وغناك\n\nق) يا رب انت وحدك\nتغفر الآثام\nتشفي كل المرضى\nوتعول الايتام\n\n5- يا رب انت قادر\nوصاحب سلطان\nوبقوةكلامك\nهاندوس على الشيطان\n\nق) يا رب انت وحدك\nتغفر الآثام\nتشفي كل المرضى\nوتعول الايتام"}, {"id": "pp175", "cat": "pp", "title": "يا روماني", "text": "1- يا روماني انا عايز اقولك\nشكراً ليك يا بطل على طول\nما انت صلاتك فيها الخير\nواللي تصلي عشانه ينول 3\n\n2- يا روماني ده مفيش ولا مرة\nولا ثانية نسيت رب القدرة\nتشكره على الحلوة والمرة\nربنا كان عنك مسئول 3\n\n3- صامت صابر للنهاية\nقلت يسوع كنزي وغنايا\nهو مفيش غيره وكفاية\nربي معايا وبيه مشغول 3\n\n4- دول ضربوك جرحوك اهانوك\nوعذبات صعبة تعبوك\nوماسبتش الفادي ابوك\nمهما عذابك كان بيطول 3"}, {"id": "pp176", "cat": "pp", "title": "يا سائح (بالقبطي)", "text": "1- بي انا خورتيس ايناف أي ايسوس\nامبير فير أو أوش خا ايفي هي إهكو\nتيك اخري ابؤيك ام ابؤنخ\nافتسوك ام افمو انتى مومي\n\nيا سائح للقاء يسوع\nلا يهمك عطش ولا جوع\nطعامك خبز الحياة\nويرويك ماء الينبوع\n\n2- بي انا خورتيس كافي ايت سيني\nموشي ام بي مويت خين او طاجرو\nاينيه خين بي مويت ان امكافه\nآري ايفميفي ايتاف مو خين بيك مي \n\nيا سائح اترك ما فات\nوأسلك في الطريق بثبات\nوإن كان في الطريق آلامات\nأذكر من في حُبك مات\n\n3- ابصالبين غوس خونت ايه تي اسمي\nخين اوراشي نيم او ثيليل\nاونيشتي امفو شيم هيت تيتشيبي\nبي ريف رويس افنا اتشي اكلوم\n\nالبوق يضرب بعد قليل\nبالفرح وصوت التهليل\nحفلة عظيمة على السحاب\nوالسهران يلبس اكليل\n\n4- افنا اي سوبتي ناك ان اوما\nافتشي ليملوم يسجين او سيو\nبيف هيت افتشيشو او ايروك\nاو اونياتك افشان جميك اك رويس\n\nراح يعدلك مكان\nمشغول بيك بقاله زمان\nقلبه متشوق إليك\nسعدك لو لقاك سهران\n\n5- تي ميت ان هوت انتى بيخريستوس\nات شوبي خين بيترا\nامبير ايرهوتي اميت كين زينوس\nبي ريف رويس ات بيترا اني اي اون\n\nيا وديعة المسيح\nيا ساكنة وسط الصخور\nلا تخافي من خطر\nحاميكي صخر الدهور\n\n6- أبخوروس ان سولومون انثو \nسيه انافوفي ايف كوتي ايرو\nاف فاي خاهان سيفي تيرو\nابجوره ابئي هؤ او سيه اريه ايرو\n\nتخت سليمان انتي\nحولك ستون جبار \nكلهم حاملين سيوف\nيحرسوكي ليل ونهار"}, {"id": "pp177", "cat": "pp", "title": "يا سلام على قُدرة ايدك", "text": "ق) يا سلام على قدرة ايدك يا ابن الله\nتنده على الميت يخرج من الموت لحياة\nجيت وفاديتني واتبنيتني\nوضمنت لي مكان في سماك\n\n1- لما الناس تفشل وتقول مستحيل\nتيجي يا سيدي وتبدل ظلام الليل\nتحيي الأمل اللي فقدناه\n\nق) يا سلام على قدرة ايدك يا ابن الله\nتنده على الميت يخرج من الموت لحياة\nجيت وفاديتني واتبنيتني\nوضمنت لي مكان في سماك\n\n2- لمَّا المرض الصعب \nيهاجم الأجساد\nتيجي تحول المرض للأختبارات\nلمسة ايدك تدي شفاء\n\nق) يا سلام على قدرة ايدك يا ابن الله\nتنده على الميت يخرج من الموت لحياة\nجيت وفاديتني واتبنيتني\nوضمنت لي مكان في سماك\n\n3- افرد ايدك \nإلمس شعب حزين تعبان\nاعلن مجدك قدام كل طبيب حيران\nوالميت اديله حياة\n\nق) يا سلام على قدرة ايدك يا ابن الله\nتنده على الميت يخرج من الموت لحياة\nجيت وفاديتني واتبنيتني\nوضمنت لي مكان في سماك"}, {"id": "pp178", "cat": "pp", "title": "يا فرحة قلبي", "text": "1- يا فرحة قلبي بربي\nتملي معايا في متاعبي\nويقولي اطمن يا ابني\nده انت اعز حبايبي\n\nق) \n\nده ابويا إله حنَّان\nعينه عليَّ كل الأيام\n\n2- يا فرحة قلبي بربي\nتملي معايا في تجاربي\nويقولي اطمن يا ابني\nحملك شايله على كتفي\n\nق) \n\nده ابويا إله حنَّان\nعينه عليَّ كل الأيام\n\n3- يا فرحة قلبي بربي\nتملي معايا في حزني\nويقولي اطمن يا ابني\nانا ابوك وهأعزي\n\nق) \n\nده ابويا إله حنَّان\nعينه عليَّ كل الأيام\n\n4- يا فرحة قلبي بربي\nتملي معايا في مرضي\nويقولي اطمن يا ابني\nدي لمسة منه ها تشفي\n\nق) \n\nده ابويا إله حنَّان\nعينه عليَّ كل الأيام\n\n5- يا فرحة قلبي بربي\nتملي معايا في ألمي\nويقولي اطمن يا ابني\nايدي هاتشبع وتغني\n\nق) \n\nده ابويا إله حنَّان\nعينه عليَّ كل الأيام\n\n6- يا فرحة قلبي بيسوعي\nلمَّا الكل تركوني\nقال لي انا حاطك في عيوني\nده انت ابني الغالي محبوبي\n\nق) \n\nده ابويا إله حنَّان\nعينه عليَّ كل الأيام\n\n7- يا فرحة قلبي بإلهي\nاللي بدمه اشتراني\nوامي العذراء بتصلي\nفي السماء عني تملي\n\nق) \n\nده ابويا إله حنَّان\nعينه عليَّ كل الأيام\n\n8- يا فرحة قلبي يا هنايا\nده يسوع مصدر عزايا\nنعمته سنده وحماية\nوشفاعة العذراء ويايا\n\nق) \n\nده ابويا إله حنَّان\nعينه عليَّ كل الأيام"}, {"id": "pp179", "cat": "pp", "title": "يا كنيسة قومي", "text": "ق) يا كنيسة قومي بالمصابيح\nنوري وقولي جاي المسيح\nعريسنا جاي ياخدنا إليه\nده جاي بمجده ومجد ابيه\n\n1- قوموا يا ابناء النور برجاء\nواستقبلوا حب واشواق\nشدوا الحقوين فالحق معين\nلحافظينه للمنتظرين\n\nق) يا كنيسة قومي بالمصابيح\nنوري وقولي جاي المسيح\nعريسنا جاي ياخدنا إليه\nده جاي بمجده ومجد ابيه\n\n2- العين مصباح تصلح بضياء\nوالزيت متاح والروح وعاء\nمصباح ماينطفيش\nيا عيني فوق ماتنزليش\n\nق) يا كنيسة قومي بالمصابيح\nنوري وقولي جاي المسيح\nعريسنا جاي ياخدنا إليه\nده جاي بمجده ومجد ابيه\n\n3- شمس المحبوب تشرق في قلوب\nالعارفينه بلا غروب\nيوقف ظلام شمس الازمان\nوالليل هناك ملهوش مكان\n\nق) يا كنيسة قومي بالمصابيح\nنوري وقولي جاي المسيح\nعريسنا جاي ياخدنا إليه\nده جاي بمجده ومجد ابيه\n\n4- بلا انفصال بلا تغيير\nوالبحر اتشال من التدبير\nيا قلبي انطق وانشد بإيمان\nيومه قريب ومجيئه حال\n\nق) يا كنيسة قومي بالمصابيح\nنوري وقولي جاي المسيح\nعريسنا جاي ياخدنا إليه\nده جاي بمجده ومجد ابيه\n\n5- نلبس اجساد بعدم فساد\nتم الخلاص الى الابد\nامين تعالى ده شوق قلبي\nمجيئك ربي على السحاب\n\nق) يا كنيسة قومي بالمصابيح\nنوري وقولي جاي المسيح\nعريسنا جاي ياخدنا إليه\nده جاي بمجده ومجد ابيه"}, {"id": "pp180", "cat": "pp", "title": "يا كنيستي يا بيت ربي", "text": "ق) يا كنيستي يا بيت ربي\nما في قلبي غيرك انت\nفي صلاتي انا بدعي من قلبي\nيحميكي ربنا يا كنيستي\n\n1- مهما حارب فينا الشيطان\nبظلم وقتل وسفك دماء\nيا كنيستي اولادك شجعان\nرضعوا منك لبن الإيمان\n\nق) يا كنيستي يا بيت ربي\nما في قلبي غيرك انت\nفي صلاتي انا بدعي من قلبي\nيحميكي ربنا يا كنيستي\n\n2- مهما قتلوا وسفكوا دماء\nاولادك شايفين السماء\nيا كنيستي نفديكي بالدماء\nنحيا ونموت على الإيمان\n\nق) يا كنيستي يا بيت ربي\nما في قلبي غيرك انت\nفي صلاتي انا بدعي من قلبي\nيحميكي ربنا يا كنيستي\n\n3- قتلوا في الكشح وابوقرقاص\nوالدم شهادة لكل الناس\nيا كنيستي افرحي بالشهداء\nاولادك في كل مكان\n\nق) يا كنيستي يا بيت ربي\nما في قلبي غيرك انت\nفي صلاتي انا بدعي من قلبي\nيحميكي ربنا يا كنيستي\n\n4- في البطرسية وطنطا كمان\nفي اسكندرية الدم سال\nمارمرقس كاروزنا زمان\nالدم شاهد للإيمان\n\nق) يا كنيستي يا بيت ربي\nما في قلبي غيرك انت\nفي صلاتي انا بدعي من قلبي\nيحميكي ربنا يا كنيستي\n\n5- ذبحوا اولادك في ليبيا\nشهداء بإيمان في ظروف صعبة\nيا كنيستي يا أم الشهداء\nانتي لينا بر ومرسا\n\nق) يا كنيستي يا بيت ربي\nما في قلبي غيرك انت\nفي صلاتي انا بدعي من قلبي\nيحميكي ربنا يا كنيستي\n\n6- قتلوا اولادك المعترفين\nفي طريق دير انبا صموئيل\nفرحوا يا كنيستي بالأكاليل\nمع الشهداء والمعترفين\n\nق) يا كنيستي يا بيت ربي\nما في قلبي غيرك انت\nفي صلاتي انا بدعي من قلبي\nيحميكي ربنا يا كنيستي\n\n7- قتلوا ابونا مينا وابونا روفائيل\nوابونا سمعان وابونا ارسانيوس\nبقوا ضمن سحابة الشهداء\nبيصلوا لينا عند الآب\n\nق) يا كنيستي يا بيت ربي\nما في قلبي غيرك انت\nفي صلاتي انا بدعي من قلبي\nيحميكي ربنا يا كنيستي\n\n8- يا كنيستي يا ارثوذكسية\nتعاليمك لينا منارة عالية\nمستقيمة عظيمة وقوية\nلجميع اجيال البشرية\n\nق) يا كنيستي يا بيت ربي\nما في قلبي غيرك انت\nفي صلاتي انا بدعي من قلبي\nيحميكي ربنا يا كنيستي"}, {"id": "pp181", "cat": "pp", "title": "يا مُحبَّاً مات", "text": "1- يا مُحباً مات عن جنس البشر\nامحوا اثمي انت اولى من غفر\nكُن مُعيناً فأنا ممن عثر\nبالخطايا يا حبيبي يا يسوع\n\n2- انت حصني وإليك المُلتجأ \nمنك ألقى بألتجائي الفرجَ\nفأعن ضعفي وولد بيَّ الرجا\nبخلاصي يا حبيبي يا يسوع\n\n3- انت تدعو الخاطئ الغر الأثيم\nلينال الخلد في دار النعيم\nوانا مهما يكون ذنبي عظيم\nلك آتي يا حبيبي يا يسوع\n\n4- انت تُحيي رجاء في القلوب\nمانحاً عفواً إذا كانت تتوب\nانت غافر الخطايا والذنوب\nفأمحوا إثمي يا حبيبي يا يسوع\n\n5- تهت في وادي الخطأ فأنظر إليَّ\nواهدني طرق الهدى واشفق عليَّ\nوانا كل الثناء مادمت حياً\nلك اهدي يا حبيبي يا يسوع\n\n6- يا كريماً جاء من أعلى سماه\nلك حمدي كل حين في الصلاة\nوإذا ما جائني يوم الوفاة\nلك نفسي يا حبيبي يا يسوع"}, {"id": "pp182", "cat": "pp", "title": "يا مريم يا ام النور", "text": "1- يا مريم يا أم النور \nانتي يا حنونة\nيا كنز الطهارة \nملأ كل المسكونة\nيا مريم ابنة يواقيم\n(عليتي على الشاروبيم) 3\n\nق) يللي اظهري يللي\nطلي بنورك طلة\nيا له من منظر\nمثله لم ينظر\n\n2- فقتي الرؤساء\nوالاربعة حيوانات\nوأيضاً الكراسي\nوالارباب والقوات\nحملتي ابن الله\n(خالق كل المخلوقات) 3\n\nق) يللي اظهري يللي\nطلي بنورك طلة\nيا له من منظر\nمثله لم ينظر\n\n3- طوباكي يا مريم\nيا ابنة صهيون\nيا سلم الأب يعقوب\nحملتي الديان\nوشفيتي كل المرضى\n(وفتحتي أعين العميان) 3\n\nق) يللي اظهري يللي\nطلي بنورك طلة\nيا له من منظر\nمثله لم ينظر\n\n4- داود ابوكي\nفي المزمور قد قال\nالرب اختار حسنك\nوزادك نور وجمال\nهذا كله مثال\n(ورموز وإشارات) 3\n\nق) يللي اظهري يللي\nطلي بنورك طلة\nيا له من منظر\nمثله لم ينظر\n\n5- يا شجرة مغروسة\nمحاطة بالنور\nبيكي يا مريم فزنا\nببهجة وسرور\nمن نال ما نلتي يا مريم\n(في سائر بي كوزموس) 3\n\nق) يللي اظهري يللي\nطلي بنورك طلة\nيا له من منظر\nمثله لم ينظر\n\n6- ليس من يشبهك\nفي الارض ولا السموات\nوالرب فضلك\nعلى كل المخلوقات\nوكم وصفوا عنك\n(في نبوات وإشارات) 3\n\nق) يللي اظهري يللي\nطلي بنورك طلة\nيا له من منظر\nمثله لم ينظر\n\n7- يا هيكل طاهر \nوحجاب القدوس\nاحفظي شعب ابنك\nقمامصة وقسوس\nوالأنبا بفنوتيوس\n(والشعب المجتمعين) 3\n\nق) يللي اظهري يللي\nطلي بنورك طلة\nيا له من منظر\nمثله لم ينظر"}, {"id": "pp183", "cat": "pp", "title": "يا منبع الأفراح", "text": "1- مين يحرمنا من احلامنا\nاللي احنا بنحلمها معاك\nشوقنا يا فادي نقف وننادي\nنعلن عن حبك وفداك\n\nق) يا منبع الافراح\nيا روح الله املانا\nعايزين فرح حقيقي\nيكبر ويزيد جوانا\n\n2- لا يفرحنا ولا يشبعنا\nخمر العالم الحزين\nلكن نفرح لما بتفتح\nابوابك لينا يا معين\n\nق) يا منبع الافراح\nيا روح الله املانا\nعايزين فرح حقيقي\nيكبر ويزيد جوانا\n\n3- لا زنزانة ولا ترسانة\nهاتوقف تسبيح الرب\nدي الفرحة الحلوة الرنانة\nتكسر كل قيود القلب\n\nق) يا منبع الافراح\nيا روح الله املانا\nعايزين فرح حقيقي\nيكبر ويزيد جوانا\n\n4- كرمة وتين مش عايزين\nلا كُتر اراضي ولا املاك\nانت امين يا رب ومين\nيسعدنا ويكفينا سواك\n\nق) يا منبع الافراح\nيا روح الله املانا\nعايزين فرح حقيقي\nيكبر ويزيد جوانا"}, {"id": "pp184", "cat": "pp", "title": "يا مؤتي الأغاني", "text": "1- تارك كل أموري لديك\nياللي ناقشني على كفيك\nانت سلامي وانا في آلامي\nوانا في الضيق شايفاني عنيك\n\nق) يا مؤتي الاغاني \nفي ليلي واحزاني\nيا ضامن سلامي\nيا يسوع راعيَّ\n\n2- رافع ايدي بسلم ليك\nدفة عمري دي ملك ايديك\nقالوا كتير فين الخير\nانت الخير وانا عايش فيه\n\nق) يا مؤتي الاغاني \nفي ليلي واحزاني\nيا ضامن سلامي\nيا يسوع راعيَّ\n\n3- بات الدمع بين الأحضان\nويا الصبح جت الالحان\nوانتصارات واختبارات\nموكب نصرك لينا كمان\n\nق) يا مؤتي الاغاني \nفي ليلي واحزاني\nيا ضامن سلامي\nيا يسوع راعيَّ\n\n4- وقت الصعب هارنم ليك\nفرحي ده قوة وليه اداريه\nولا انسان ولا شيطان\nينزع فرح انت اللي عاطيه\n\nق) يا مؤتي الاغاني \nفي ليلي واحزاني\nيا ضامن سلامي\nيا يسوع راعيَّ"}, {"id": "pp185", "cat": "pp", "title": "يا يسوع انا ابنك", "text": "1- يا يسوع انا ابنك\nانا ابنك مغلوب لزمان\nانا ابنك خدعه الشيطان\nحررني قويني انا ابنك\n\nق) يا يسوع انا ابنك\nانا ابنك بالتوبة جاي\nانا ابنك ولحضنك راجع\nاقبلني ثبتني انا ابنك\n\n2- يا يسوع انا ابنك\nانا ابنك يائس محتاج\nانا ابنك محتاج لرجاء\nبالنعمة اوهبني انا ابنك\n\nق) يا يسوع انا ابنك\nانا ابنك بالتوبة جاي\nانا ابنك ولحضنك راجع\nاقبلني ثبتني انا ابنك\n\n3- يا يسوع انا ابنك\nانا ابنك راجع مشتاق\nانا ابنك وكنت ضال\nاقبلني طهرني انا ابنك\n\nق) يا يسوع انا ابنك\nانا ابنك بالتوبة جاي\nانا ابنك ولحضنك راجع\nاقبلني ثبتني انا ابنك\n\n4- يا يسوع انا ابنك\nانا ابنك حواليَّ ضيقات\nانا ابنك وواثق فيك\nاسندني ارحمني انا ابنك\n\nق) يا يسوع انا ابنك\nانا ابنك بالتوبة جاي\nانا ابنك ولحضنك راجع\nاقبلني ثبتني انا ابنك\n\n5- يا يسوع انا ابنك\nانا ابنك اجذبني وراك\nانا ابنك امسك بإيدي\nدربني ارشدني انا ابنك\n\nق) يا يسوع انا ابنك\nانا ابنك بالتوبة جاي\nانا ابنك ولحضنك راجع\nاقبلني ثبتني انا ابنك\n\n6- يا يسوع انا ابنك\nانا ابنك وبترجاك\nانا ابنك متعشم فيك\nارحمني سامحني انا ابنك\n\nق) يا يسوع انا ابنك\nانا ابنك بالتوبة جاي\nانا ابنك ولحضنك راجع\nاقبلني ثبتني انا ابنك\n\n7- يا يسوع انا ابنك\nانا ابنك عيني شايفاك\nانا ابنك سلمتك قلبي\nكرسني ارعاني انا ابنك\n\nق) يا يسوع انا ابنك\nانا ابنك بالتوبة جاي\nانا ابنك ولحضنك راجع\nاقبلني ثبتني انا ابنك\n\n8- يا يسوع انا ابنك\nانا ابنك وبتمناك\nانا ابنك شوقي سماك\nورثني ملكني انا ابنك\n\nق) يا يسوع انا ابنك\nانا ابنك بالتوبة جاي\nانا ابنك ولحضنك راجع\nاقبلني ثبتني انا ابنك\n\n9- يا يسوع انا ابنك\nانا ابنك هدفي سماك\nانا ابنك وبنعمة منك\nاتبارك اتعزى انا ابنك\n\nق) يا يسوع انا ابنك\nانا ابنك بالتوبة جاي\nانا ابنك ولحضنك راجع\nاقبلني ثبتني انا ابنك\n\n10- يا يسوع انا ابنك\nانا ابنك واثق بإيمان\nانا ابنك ميراثي امجاد\nاسبح وارنم إليك في سماك\n\nق) يا يسوع انا ابنك\nانا ابنك بالتوبة جاي\nانا ابنك ولحضنك راجع\nاقبلني ثبتني انا ابنك"}, {"id": "pp186", "cat": "pp", "title": "يا اللي مليتي", "text": "1- ياللي مليتي الدنيا افراح\nببركة صلواتك يا تماف\nالكل بيكي هنا فرحان\nامي ايريني يعني سلام\n\nق) فرحك ملأ الكون تسبيح\nيا تماف يا عروس المسيح\nالعذراء مريم امك\nكانت ليكي اعظم شفيع\n\n2- يااللي صادقتي ابوسيفين\nوكان ليكي صديق معين\nفي ضيقك وكل آلامك\nكان بيشفع للمسيح\n\nق) فرحك ملأ الكون تسبيح\nيا تماف يا عروس المسيح\nالعذراء مريم امك\nكانت ليكي اعظم شفيع\n\n3- ياللي شفاعتك انتي قوية \nفي السماء امام يسوع\nيا تماف انتي اغلى ماليَّ\nولكل شعب ايسوس\n\nق) فرحك ملأ الكون تسبيح\nيا تماف يا عروس المسيح\nالعذراء مريم امك\nكانت ليكي اعظم شفيع\n\n4- ياللا يا خاطي قوم الان\nواطلب بتوبة من الحنَّان\nيديك نعمة وغفران\nبصلواتك يا امنا تماف\n\nق) فرحك ملأ الكون تسبيح\nيا تماف يا عروس المسيح\nالعذراء مريم امك\nكانت ليكي اعظم شفيع\n\n5- ياللا يا مرضى يا موجوعين\nاطلبوا اعظم طبيب\nواتشفعوا بالأم ايريني\nده هو ليها اعظم حبيب\n\nق) فرحك ملأ الكون تسبيح\nيا تماف يا عروس المسيح\nالعذراء مريم امك\nكانت ليكي اعظم شفيع\n\n6- ياللا نصلي بكل دموع\nونطلب من رب الجموع\nبشفاعة تماف ايريني\nيتحقق لينا المطلوب\n\nق) فرحك ملأ الكون تسبيح\nيا تماف يا عروس المسيح\nالعذراء مريم امك\nكانت ليكي اعظم شفيع"}, {"id": "pp187", "cat": "pp", "title": "ياليتني اكرمكِ", "text": "ق) ياليتني اكرمكي\n يا عذراء يا شفيعتي\nيا ام يسوع\nصوتك تملي في وداني\n\nوصورتك دي بركة ايامي\nحُبك انتي في وجداني\nساعديني باركيني\nقوي ايماني\n\n1- اطلبي لينا سلام\nنوري كل ظلام\nامسكي ايدينا بإيديكي\nيا امي طول الأيام\n\nق) ياليتني اكرمكي\n يا عذراء يا شفيعتي\nيا ام يسوع\nصوتك تملي في وداني\n\nوصورتك دي بركة ايامي\nحُبك انتي في وجداني\nساعديني باركيني\nقوي ايماني\n\n2- شعبك دايماً فرحان\nبصلاتك للديان\nواثق بصلاتك يا بتول\nهأثبت في ايماني طول الزمان\n\nق) ياليتني اكرمكي\n يا عذراء يا شفيعتي\nيا ام يسوع\nصوتك تملي في وداني\n\nوصورتك دي بركة ايامي\nحُبك انتي في وجداني\nساعديني باركيني\nقوي ايماني\n\n3- قلبك يا امي حنون\nنبع بركات علطول\nلك خاطي يترجاكي\nيرجع لإلهه ويتوب\n\nق) ياليتني اكرمكي\n يا عذراء يا شفيعتي\nيا ام يسوع\nصوتك تملي في وداني\n\nوصورتك دي بركة ايامي\nحُبك انتي في وجداني\nساعديني باركيني\nقوي ايماني\n\n4- أولادك فرحانين\nبشفاعتك كل حين\nمن أجل المرضى المتعبين\nوكل اخواتهم المساكين\n\nق) ياليتني اكرمكي\n يا عذراء يا شفيعتي\nيا ام يسوع\nصوتك تملي في وداني\n\nوصورتك دي بركة ايامي\nحُبك انتي في وجداني\nساعديني باركيني\nقوي ايماني\n\n5- صلواتك للحاضرين\nواخوتنا الغائبين\nاطلبي ليهم من ابنك\nيا مريم طول السنين\n\nق) ياليتني اكرمكي\n يا عذراء يا شفيعتي\nيا ام يسوع\nصوتك تملي في وداني\n\nوصورتك دي بركة ايامي\nحُبك انتي في وجداني\nساعديني باركيني\nقوي ايماني"}, {"id": "pp188", "cat": "pp", "title": "يسوع جالس", "text": "1- يسوع جالس في البستان\nمن خمر الحزن سكران\nعالم انه سيهان\nمن اجل خلاص البشرية\n\nق) حاشا يا رب ان تصلي\nانا معك اينما تذهب\nان مُت يا اموت معاك\nوان عشت يا اعيش معاك\n\n2- قال لابد ان اصلب\nواجوز ضيقة وتعب\nيصلبوني بدون سبب\nمن اجل خلاص البشرية\n\nق) حاشا يا رب ان تصلي\nانا معك اينما تذهب\nان مُت يا اموت معاك\nوان عشت يا اعيش معاك\n\n3- في هذه الليلة بثبات\nتنكرني ثلاثة مرات\nحاشا يا رب ان انساك\nان مُت سأموت معاك\n\nق) حاشا يا رب ان تصلي\nانا معك اينما تذهب\nان مُت يا اموت معاك\nوان عشت يا اعيش معاك\n\n4- قال قبل صياح الديك\nيا بطرس تحلف بأبيك\nانك لم تكن لي شريك\nولا تعرف لي جنسية\n\nق) حاشا يا رب ان تصلي\nانا معك اينما تذهب\nان مُت يا اموت معاك\nوان عشت يا اعيش معاك\n\n5- مرت الجارية برؤوية\nجاني ليه وكنت معاه\nانكر معرفته بيا\nولا اعرف له جنسية\n\nق) حاشا يا رب ان تصلي\nانا معك اينما تذهب\nان مُت يا اموت معاك\nوان عشت يا اعيش معاك\n\n6- لما الديك ابتدا يصيح\nتذكر كلام المسيح\nبكى بحسرة وقال صحيح\nانا قد فعلت الخطية\n\nق) حاشا يا رب ان تصلي\nانا معك اينما تذهب\nان مُت يا اموت معاك\nوان عشت يا اعيش معاك\n\n7- ثم اخذوه لدار الوالي\nليكن صلبه في الحالي\nلم يقول اسمعوا اقوالي\nبل سلم نفسه ضحية\n\nق) حاشا يا رب ان تصلي\nانا معك اينما تذهب\nان مُت يا اموت معاك\nوان عشت يا اعيش معاك\n\n8- التلاميذ ودعوه ببكاء\nوقالوا إلى اللقاء\nيا سيدنا في السماء\nيا سعادتنا الابدية\n\nق) حاشا يا رب ان تصلي\nانا معك اينما تذهب\nان مُت يا اموت معاك\nوان عشت يا اعيش معاك"}, {"id": "pp189", "cat": "pp", "title": "يسوع هو إلهنا", "text": "1- يسوع هو إلهنا\nوابونا الحبيب\nلأنه رجاؤنا\nوملجأنا الوحيد\n\nق) المجد ليه\nهانرنم ليه\nنكرز ونبشر \nدايماً بيه\n\n2- يسوع إلهنا القوي\nوابونا العظيم\nفي الضيق لنا سنداً\nوضامناً معين\n\nق) المجد ليه\nهانرنم ليه\nنكرز ونبشر \nدايماً بيه\n\n3- يسوع إلهنا القادر\nعلى كل امر عسير\nينجينا من الخطر\nوحمانا الوطيد\n\nق) المجد ليه\nهانرنم ليه\nنكرز ونبشر \nدايماً بيه\n\n4- يسوع إلهنا الطيب\nلكل إنسان مريض\nبلمسته يشفي المرضى\nمهما يكون مرض خطير\n\nق) المجد ليه\nهانرنم ليه\nنكرز ونبشر \nدايماً بيه\n\n5- يسوع إلهنا الغافر\nالخطايا والذنوب\nبكلمة واحدة بسلطانه\nيحيينا من بعد الموت\n\nق) المجد ليه\nهانرنم ليه\nنكرز ونبشر \nدايماً بيه\n\n6- يسوع إلهنا الحنون\nعلى الارامل والايتام\nويدبر كل الامور\nويشبع كل محتاج\n\nق) المجد ليه\nهانرنم ليه\nنكرز ونبشر \nدايماً بيه"}]);
